// ─── Email template variables ────────────────────────────────────────────────

const TEMPLATE_VARS = [
  { token: '{{lead.name}}',     label: 'Nom de l\'entreprise' },
  { token: '{{lead.email}}',    label: 'Courriel' },
  { token: '{{lead.phone}}',    label: 'Téléphone' },
  { token: '{{lead.website}}',  label: 'Site web' },
  { token: '{{lead.address}}',  label: 'Adresse' },
  { token: '{{lead.category}}', label: 'Catégorie' },
  { token: '{{company.name}}',  label: 'Mon entreprise' },
  { token: '{{company.email}}', label: 'Mon courriel' },
  { token: '{{sender.name}}',   label: 'Mon nom' },
  { token: '{{search.title}}',  label: 'Titre de la prospection' },
];

function resolveTemplateVars(text: string, lead: any, company: any, senderName: string, searchTitle: string): string {
  const address = [lead.address].filter(Boolean).join(', ');
  return text
    .split('{{lead.name}}').join(lead.name ?? '')
    .split('{{lead.email}}').join(lead.email ?? '')
    .split('{{lead.phone}}').join(lead.phone ?? '')
    .split('{{lead.website}}').join(lead.website ?? '')
    .split('{{lead.address}}').join(address)
    .split('{{lead.category}}').join(lead.category ?? '')
    .split('{{company.name}}').join(company?.name ?? '')
    .split('{{company.email}}').join(company?.email ?? '')
    .split('{{sender.name}}').join(senderName)
    .split('{{search.title}}').join(searchTitle);
}

/** Signature appended to every prospect email, with the same fallback everywhere. */
function companySignature(company: any): string {
  return company?.brandEmailSignature?.trim() || `Cordialement,\n${company?.name ?? ''}`;
}

// ─── Template selection ───────────────────────────────────────────────────────

type ProspectTemplate = {
  id: string;
  name: string;
  channel: 'email' | 'sms';
  subject: string;
  body: string;
  defaultStatus: string | null;
};

function templatesFor(templates: any[], channel: 'email' | 'sms'): ProspectTemplate[] {
  return (templates as ProspectTemplate[]).filter(t => t.channel === channel);
}

/**
 * The model a lead opens with: the one claiming its status, else a model tied to
 * no status in particular, else the first one. Returns null when the channel has
 * no model at all.
 */
function pickTemplateForStatus(
  templates: any[],
  channel: 'email' | 'sms',
  status: string | null | undefined,
): ProspectTemplate | null {
  const list = templatesFor(templates, channel);
  if (list.length === 0) return null;
  return (
    (status ? list.find(t => t.defaultStatus === status) : undefined) ??
    list.find(t => !t.defaultStatus) ??
    list[0]
  );
}

// ─── Templates modal (email + sms models) ────────────────────────────────────

const NEW_TEMPLATE = 'new';

function TemplatesModal({
  searchId,
  searchTitle,
  statusConfigs,
  onClose,
}: {
  searchId: string;
  searchTitle: string;
  statusConfigs: LeadStatusConfig[];
  onClose: () => void;
}) {
  // Kept raw (not defaulted to []) so the effects below can tell "still loading"
  // from "no model yet".
  const { data: templatesData, refetch } = useQuery(
    // @ts-ignore -- generated by Wasp on next restart
    getProspectTemplates,
    { searchId },
  );
  const templates: any[] = (templatesData as any[]) ?? [];
  const { data: company } = useQuery(getCurrentCompany);
  const { data: senderInfo } = useQuery(
    // @ts-ignore -- generated by Wasp on next restart
    getMailSenderAddress,
  );

  const [channel, setChannel] = useState<'email' | 'sms'>('email');
  const [selectedId, setSelectedId] = useState<string>(NEW_TEMPLATE);
  const [name, setName] = useState('');
  const [subject, setSubject] = useState('');
  const [body, setBody] = useState('');
  const [defaultStatus, setDefaultStatus] = useState('');
  const [saving, setSaving] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [generating, setGenerating] = useState(false);
  const [preview, setPreview] = useState(false);
  const [initialized, setInitialized] = useState(false);
  const subjectRef = useRef<HTMLInputElement>(null);
  const bodyRef = useRef<HTMLTextAreaElement>(null);

  const list = useMemo(() => templatesFor(templates, channel), [templatesData, channel]);
  const isSms = channel === 'sms';

  // Open on the first existing model rather than an empty form.
  useEffect(() => {
    if (initialized || templatesData === undefined) return;
    const first = templatesFor(templates, 'email')[0] ?? templatesFor(templates, 'sms')[0];
    if (first) {
      setChannel(first.channel);
      setSelectedId(first.id);
    }
    setInitialized(true);
  }, [templatesData, initialized]);

  // Load a model into the editor when the *selection* changes. Deliberately not
  // on every `templatesData` change: an action (saving, or generating with the
  // AI — it shares entities with this query) makes wasp refetch, and reloading
  // then would wipe whatever is being written, generated text included.
  const loadedIdRef = useRef<string | null>(null);
  useEffect(() => {
    if (loadedIdRef.current === selectedId) return;
    if (selectedId === NEW_TEMPLATE) {
      setName('');
      setSubject('');
      setBody('');
      setDefaultStatus('');
      loadedIdRef.current = selectedId;
      return;
    }
    const t = templates.find((x: any) => x.id === selectedId);
    if (!t) return; // still loading — retry on the next data change
    setName(t.name);
    setSubject(t.subject ?? '');
    setBody(t.body ?? '');
    setDefaultStatus(t.defaultStatus ?? '');
    loadedIdRef.current = selectedId;
  }, [selectedId, templatesData]);

  function selectChannel(next: 'email' | 'sms') {
    setChannel(next);
    setPreview(false);
    const first = templatesFor(templates, next)[0];
    setSelectedId(first ? first.id : NEW_TEMPLATE);
  }

  function insertToken(token: string, field: 'subject' | 'body') {
    if (field === 'subject' && subjectRef.current) {
      const el = subjectRef.current;
      const start = el.selectionStart ?? subject.length;
      const end = el.selectionEnd ?? subject.length;
      const next = subject.slice(0, start) + token + subject.slice(end);
      setSubject(next);
      setTimeout(() => {
        el.focus();
        el.setSelectionRange(start + token.length, start + token.length);
      }, 0);
    } else if (field === 'body' && bodyRef.current) {
      const el = bodyRef.current;
      const start = el.selectionStart ?? body.length;
      const end = el.selectionEnd ?? body.length;
      const next = body.slice(0, start) + token + body.slice(end);
      setBody(next);
      setTimeout(() => {
        el.focus();
        el.setSelectionRange(start + token.length, start + token.length);
      }, 0);
    } else if (field === 'body') {
      setBody(b => b + token);
    } else {
      setSubject(s => s + token);
    }
  }

  // Track which field was last focused for token insertion
  const [lastFocus, setLastFocus] = useState<'subject' | 'body'>('body');

  const sampleLead = {
    name: 'Exemple Inc.',
    email: 'contact@exemple.com',
    phone: '514-555-0100',
    website: 'https://exemple.com',
    address: '123 Rue Principale, Montréal, QC',
    category: 'Agence web',
  };

  // Mirrors exactly what the send modals build when the model is applied.
  const previewSubject = resolveTemplateVars(subject, sampleLead, company, 'Votre nom', searchTitle);
  const previewBody = isSms
    ? resolveTemplateVars(body, sampleLead, company, 'Votre nom', searchTitle)
    : resolveTemplateVars(body, sampleLead, company, 'Votre nom', searchTitle)
        + '\n\n' + companySignature(company);
  const companyEmail = (company as any)?.email ?? '';
  const fromEmail = (senderInfo as any)?.fromEmail ?? '';
  const fromName = (senderInfo as any)?.fromName || (company as any)?.name || 'Gestia';
  const previewSms = smsSegments(previewBody);

  async function handleGenerate() {
    setGenerating(true);
    try {
      const result = await (generateProspectEmailTemplate as any)({
        searchId,
        channel,
        currentSubject: isSms ? null : subject.trim() || null,
        currentBody: body.trim() || null,
      });
      if (!isSms && result.subject) setSubject(result.subject);
      if (result.body) setBody(result.body);
      setPreview(false);
      toast.success('Modèle généré par l\'IA');
    } catch (err: any) {
      toast.error(err?.message || 'Erreur lors de la génération');
    } finally {
      setGenerating(false);
    }
  }

  async function handleSave() {
    if (!body.trim()) {
      toast.error(isSms ? 'Le message ne peut pas être vide' : 'Le corps ne peut pas être vide');
      return;
    }
    setSaving(true);
    try {
      const saved = await (upsertProspectTemplate as any)({
        id: selectedId === NEW_TEMPLATE ? null : selectedId,
        searchId,
        channel,
        name,
        subject,
        body,
        defaultStatus: defaultStatus || null,
      });
      toast.success('Modèle enregistré');
      setSelectedId(saved.id);
      refetch();
    } catch (err: any) {
      toast.error(err?.message || 'Erreur');
    } finally {
      setSaving(false);
    }
  }

  async function handleDelete() {
    if (selectedId === NEW_TEMPLATE) return;
    setDeleting(true);
    try {
      await (deleteProspectTemplate as any)({ id: selectedId });
      toast.success('Modèle supprimé');
      const remaining = list.filter(t => t.id !== selectedId);
      setSelectedId(remaining[0]?.id ?? NEW_TEMPLATE);
      refetch();
    } catch (err: any) {
      toast.error(err?.message || 'Erreur');
    } finally {
      setDeleting(false);
    }
  }

  const isExisting = selectedId !== NEW_TEMPLATE;
  const statusLabel = (key: string | null) =>
    statusConfigs.find(s => s.key === key)?.label ?? key ?? '';

  return (
    <div className='flex flex-col gap-0' style={{ maxHeight: '80vh', overflow: 'hidden' }}>
      {/* Channel tabs */}
      <div className='flex items-center gap-2 pb-3 border-b border-line'>
        <div className='flex items-center border border-line rounded-lg overflow-hidden text-xs font-medium'>
          <button
            type='button'
            className={`px-3 py-1.5 flex items-center gap-1.5 transition-colors ${channel === 'email' ? 'bg-accent-600 text-white' : 'text-muted hover:bg-canvas'}`}
            onClick={() => selectChannel('email')}
          >
            <LuMail size={13} />
            Courriel ({templatesFor(templates, 'email').length})
          </button>
          <button
            type='button'
            className={`px-3 py-1.5 flex items-center gap-1.5 transition-colors ${channel === 'sms' ? 'bg-accent-600 text-white' : 'text-muted hover:bg-canvas'}`}
            onClick={() => selectChannel('sms')}
          >
            <LuMessageSquare size={13} />
            SMS ({templatesFor(templates, 'sms').length})
          </button>
        </div>
        <span className='text-xs text-muted ml-auto hidden sm:block'>
          Un modèle par statut est proposé automatiquement à l'envoi.
        </span>
      </div>

      {/* Model list */}
      <div className='flex flex-wrap items-center gap-1.5 py-3 border-b border-line'>
        {list.map(t => (
          <button
            key={t.id}
            type='button'
            onClick={() => { setSelectedId(t.id); setPreview(false); }}
            className={`text-xs px-2.5 py-1 rounded-full border transition-colors flex items-center gap-1.5 ${
              selectedId === t.id
                ? 'bg-accent-50 border-accent-500 text-ink'
                : 'bg-canvas border-line text-muted hover:border-accent-400 hover:text-ink'
            }`}
          >
            {t.name}
            {t.defaultStatus && (
              <span className='text-[10px] px-1.5 py-0.5 rounded-full bg-white border border-line text-muted'>
                {statusLabel(t.defaultStatus)}
              </span>
            )}
          </button>
        ))}
        <button
          type='button'
          onClick={() => { setSelectedId(NEW_TEMPLATE); setPreview(false); }}
          className={`text-xs px-2.5 py-1 rounded-full border border-dashed transition-colors flex items-center gap-1 ${
            selectedId === NEW_TEMPLATE
              ? 'bg-accent-50 border-accent-500 text-ink'
              : 'border-line text-muted hover:border-accent-400 hover:text-ink'
          }`}
        >
          <LuPlus size={12} />
          Nouveau modèle
        </button>
      </div>

      {/* Variables panel */}
      <div className='px-1 py-3 border-b border-line'>
        <p className='text-xs text-muted mb-2'>
          Cliquez sur une variable pour l'insérer dans {lastFocus === 'subject' && !isSms ? 'l\'objet' : 'le message'} :
        </p>
        <div className='flex flex-wrap gap-1.5'>
          {TEMPLATE_VARS.map(v => (
            <button
              key={v.token}
              type='button'
              onClick={() => insertToken(v.token, isSms ? 'body' : lastFocus)}
              className='text-xs px-2 py-0.5 rounded-full bg-violet-50 text-violet-700 border border-violet-200 hover:bg-violet-100 font-mono transition-colors'
            >
              {v.token}
            </button>
          ))}
        </div>
      </div>

      {/* Toggle preview + AI button */}
      <div className='flex items-center justify-between pt-3 pb-1'>
        <button
          type='button'
          className='btn-ghost px-2 py-1 text-violet-500 flex items-center gap-1.5 text-xs'
          onClick={handleGenerate}
          disabled={generating || saving || deleting}
          title={generating ? 'Génération…' : 'Générer avec l\'IA'}
        >
          {generating ? <LuLoader size={13} className='animate-spin' /> : <LuWand size={13} />}
          {generating ? 'Génération…' : body.trim() ? 'Améliorer avec l\'IA' : 'Générer avec l\'IA'}
        </button>
        <button
          type='button'
          onClick={() => setPreview(p => !p)}
          className='flex items-center gap-1.5 text-xs text-muted hover:text-ink'
        >
          {preview ? <LuEyeOff size={13} /> : <LuEye size={13} />}
          {preview ? 'Éditer' : 'Aperçu complet (données fictives)'}
        </button>
      </div>

      <div className='flex-1 overflow-y-auto flex flex-col gap-4 pr-1'>
        {preview ? (
          isSms ? (
            <div className='rounded-xl border border-line overflow-hidden'>
              <dl className='text-xs bg-canvas-100 px-3 py-2.5 space-y-1 border-b border-line'>
                <EmailPreviewRow label='De' value={'Votre numéro Telnyx'} />
                <EmailPreviewRow label='À' value={sampleLead.phone} />
              </dl>
              <div className='text-sm whitespace-pre-wrap px-3 py-3 min-h-[120px]'>
                {body.trim() ? previewBody : <span className='text-muted italic'>Message vide</span>}
              </div>
              <div className='text-xs text-muted px-3 py-2 border-t border-line bg-canvas-100'>
                {previewSms.chars} caractère(s) · {previewSms.segments} SMS
                {previewSms.unicode ? ' · caractères spéciaux (limite 70/SMS)' : ''}
              </div>
            </div>
          ) : (
            <div className='rounded-xl border border-line overflow-hidden'>
              <dl className='text-xs bg-canvas-100 px-3 py-2.5 space-y-1 border-b border-line'>
                <EmailPreviewRow
                  label='De'
                  value={fromEmail ? `${fromName} <${fromEmail}>` : fromName}
                />
                <EmailPreviewRow label='À' value={sampleLead.email} />
                <EmailPreviewRow label='Cc' value={companyEmail || '—'} />
                <EmailPreviewRow
                  label='Répondre à'
                  value={companyEmail || 'Aucun courriel d’entreprise — les réponses seront perdues'}
                />
                <EmailPreviewRow label='Objet' value={previewSubject || 'Aucun objet'} />
              </dl>
              <div className='text-sm whitespace-pre-wrap px-3 py-3 min-h-[160px]'>
                {body.trim() ? previewBody : <span className='text-muted italic'>Corps vide</span>}
              </div>
            </div>
          )
        ) : (
          <div className='flex flex-col gap-4'>
            <div className='flex flex-col sm:flex-row gap-3'>
              <div className='flex-1'>
                <label className='label'>Nom du modèle</label>
                <input
                  className='input mt-1 w-full'
                  value={name}
                  onChange={e => setName(e.target.value)}
                  placeholder={isSms ? 'Ex. Relance rapide' : 'Ex. Premier contact'}
                />
              </div>
              <div className='sm:w-56'>
                <label className='label'>Proposé par défaut pour</label>
                <select
                  className='input mt-1 w-full'
                  value={defaultStatus}
                  onChange={e => setDefaultStatus(e.target.value)}
                >
                  <option value=''>Aucun statut en particulier</option>
                  {statusConfigs.map(s => (
                    <option key={s.key} value={s.key}>{s.label}</option>
                  ))}
                </select>
              </div>
            </div>
            {!isSms && (
              <div>
                <label className='label'>Objet</label>
                <MagicInput
                  ref={subjectRef}
                  className='input mt-1 w-full'
                  value={subject}
                  onChange={e => setSubject(e.target.value)}
                  onFocus={() => setLastFocus('subject')}
                  placeholder={`Ex. {{lead.name}} — Prise de contact`}
                />
              </div>
            )}
            <div>
              <label className='label'>{isSms ? 'Texte du SMS' : 'Corps du message'}</label>
              <MagicTextarea
                ref={bodyRef}
                className={`input mt-1 w-full resize-y font-mono text-sm ${isSms ? 'min-h-[120px]' : 'min-h-[200px]'}`}
                value={body}
                onChange={e => setBody(e.target.value)}
                onFocus={() => setLastFocus('body')}
                placeholder={isSms
                  ? `Bonjour {{lead.name}}, ici {{company.name}}. ...`
                  : `Bonjour,\n\nJe me permets de vous contacter au sujet de {{lead.name}}...\n\nCordialement,\n{{sender.name}}`}
              />
              {isSms && (
                <div className='text-xs text-muted mt-1'>
                  Aperçu avec données fictives : {previewSms.chars} caractère(s) · {previewSms.segments} SMS
                  {previewSms.unicode ? ' · caractères spéciaux (limite 70/SMS)' : ''}
                </div>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Actions */}
      <div className='flex items-center justify-between pt-4 border-t border-line mt-2'>
        <div>
          {isExisting && (
            <button
              type='button'
              className='btn-ghost text-red-600 hover:bg-red-50 gap-1.5 text-sm'
              onClick={handleDelete}
              disabled={deleting || saving || generating}
            >
              {deleting ? <LuLoader size={14} className='animate-spin' /> : <LuTrash2 size={14} />}
              Supprimer
            </button>
          )}
        </div>
        <div className='flex items-center gap-2'>
          <button type='button' className='btn-ghost' onClick={onClose}>Fermer</button>
          <button
            type='button'
            className='btn-primary gap-2'
            onClick={handleSave}
            disabled={saving || generating}
          >
            {saving ? <LuLoader size={14} className='animate-spin' /> : <LuSave size={14} />}
            {isExisting ? 'Mettre à jour' : 'Créer le modèle'}
          </button>
        </div>
      </div>
    </div>
  );
}

// ─── Add lead modal ──────────────────────────────────────────────────────────

function AddLeadModal({
  searchId,
  statusConfigs,
  onClose,
  onCreated,
}: {
  searchId: string;
  statusConfigs: LeadStatusConfig[];
  onClose: () => void;
  onCreated: (lead: any) => void;
}) {
  // Opened from the + on the Nouveau column, so that column is the default.
  const [status, setStatus] = useState<string>(
    statusConfigs.find(s => s.key === 'nouveau')?.key ?? statusConfigs[0]?.key ?? 'nouveau',
  );
  const [source, setSource] = useState<string>('manual');

  async function handleSave(values: LeadFormValues) {
    if (!values.name) {
      toast.error("Le nom de l'entreprise est requis");
      return;
    }
    try {
      const lead = await (createLead as any)({ searchId, ...values, status, source });
      toast.success(`${values.name} ajouté`);
      onCreated(lead);
      onClose();
    } catch (err: any) {
      toast.error(err?.message || "Erreur lors de l'ajout");
    }
  }

  return (
    <LeadEditForm
      initialValues={{ name: '', phone: '', email: '', website: '', address: '', category: '' }}
      onSave={handleSave}
      onCancel={onClose}
      submitLabel='Ajouter le prospect'
      savingLabel='Ajout…'
      extraFields={
        <>
          <div>
            <label className='label'>Statut</label>
            <select className='input' value={status} onChange={e => setStatus(e.target.value)}>
              {statusConfigs.map(s => (
                <option key={s.key} value={s.key}>{s.label}</option>
              ))}
            </select>
          </div>
          <div>
            <label className='label'>Provenance</label>
            <select className='input' value={source} onChange={e => setSource(e.target.value)}>
              {LEAD_SOURCES.map(s => (
                <option key={s.key} value={s.key}>{s.label}</option>
              ))}
            </select>
          </div>
        </>
      }
    />
  );
}

// ─── Prospect email modal ────────────────────────────────────────────────────

function ProspectEmailModal({ lead, searchTitle, onClose, onSent }: { lead: Lead; searchTitle: string; onClose: () => void; onSent: () => void }) {
  const identifier = (lead as any).placeId ?? lead.id;
  const { canSend: emailCanSend, reason: emailReason } = useEmailCapability();
  const { data: company } = useQuery(getCurrentCompany);
  const { data: draft } = useQuery(
    // @ts-ignore -- generated by Wasp on next restart
    getLeadEmailDraft,
    { identifier },
  );
  const { data: templatesData } = useQuery(
    // @ts-ignore -- generated by Wasp on next restart
    getProspectTemplates,
    { searchId: lead.searchId },
  );
  const emailTemplates = useMemo(
    () => templatesFor((templatesData as any[]) ?? [], 'email'),
    [templatesData],
  );
  const { data: sentLogs = [], refetch: refetchLogs } = useQuery(
    // @ts-ignore -- generated by Wasp on next restart
    getLeadEmailLogs,
    { identifier },
  );

  const [expandedLogId, setExpandedLogId] = useState<string | null>(null);
  const [to, setTo] = useState<string>('');
  const [cc, setCc] = useState<string>('');
  const [subject, setSubject] = useState<string>(`${lead.name} — Prise de contact`);
  const [body, setBody] = useState<string>('');
  const [sending, setSending] = useState(false);
  const [savingDraft, setSavingDraft] = useState(false);
  const [clearingStatus, setClearingStatus] = useState(false);
  const [generating, setGenerating] = useState(false);
  const [initialized, setInitialized] = useState(false);
  const [fromTemplate, setFromTemplate] = useState(false);
  // Model chosen in the picker — starts on the one mapped to the lead's status.
  const [templateId, setTemplateId] = useState<string>('');

  // Populate fields from draft > template > defaults once data loads
  useEffect(() => {
    if (initialized) return;
    if (draft === undefined || company === undefined || templatesData === undefined) return;
    const companyEmail = (company as any)?.email ?? '';
    const senderName = (company as any)?.senderName ?? '';
    const statusTemplate = pickTemplateForStatus(templatesData as any[], 'email', (lead as any).status);
    setTemplateId(statusTemplate?.id ?? '');
    if ((draft as any)?.body) {
      // Saved draft takes priority
      setTo((draft as any).to || (lead as any).email || '');
      setCc((draft as any).cc || companyEmail);
      setSubject((draft as any).subject || `${lead.name} — Prise de contact`);
      setBody((draft as any).body);
    } else if (statusTemplate?.body) {
      // No draft — apply the status model with resolved variables
      const sig = companySignature(company);
      const resolvedSubject = resolveTemplateVars(statusTemplate.subject || '', lead, company, senderName, searchTitle);
      const resolvedBody    = resolveTemplateVars(statusTemplate.body,    lead, company, senderName, searchTitle);
      setTo((lead as any).email || '');
      setCc(companyEmail);
      setSubject(resolvedSubject || `${lead.name} — Prise de contact`);
      setBody(resolvedBody + '\n\n' + sig);
      setFromTemplate(true);
    } else {
      setTo((lead as any).email || '');
      setCc(companyEmail);
    }
    setInitialized(true);
  }, [draft, company, templatesData, initialized]);

  async function handleSaveDraft() {
    setSavingDraft(true);
    try {
      await (saveLeadEmailDraft as any)({ identifier, to, cc, subject, body });
      toast.success('Brouillon enregistré');
    } catch (err: any) {
      toast.error(err?.message || 'Erreur');
    } finally {
      setSavingDraft(false);
    }
  }

  function handleApplyTemplate(id?: string) {
    const tmpl = emailTemplates.find(t => t.id === (id ?? templateId));
    if (!tmpl?.body) {
      toast.error('Aucun modèle de courriel pour cette prospection');
      return;
    }
    const senderName = (company as any)?.senderName ?? '';
    const sig = companySignature(company);
    const resolvedSubject = resolveTemplateVars(tmpl.subject || '', lead, company, senderName, searchTitle);
    const resolvedBody    = resolveTemplateVars(tmpl.body,    lead, company, senderName, searchTitle);
    setSubject(resolvedSubject || `${lead.name} — Prise de contact`);
    setBody(resolvedBody + '\n\n' + sig);
    setFromTemplate(true);
    toast.success(`Modèle « ${tmpl.name} » appliqué`);
  }

  async function handleGenerate() {
    setGenerating(true);
    try {
      const result = await (generateProspectEmail as any)({
        searchId: lead.searchId,
        leadName: lead.name,
        leadCategory: (lead as any).category ?? null,
        leadAddress: (lead as any).address ?? null,
        leadEmail: (lead as any).email ?? null,
        currentSubject: subject.trim() || null,
        currentBody: body.trim() || null,
      });
      if (result.subject) setSubject(result.subject);
      if (result.body) setBody(result.body);
      toast.success('Brouillon généré');
    } catch (err: any) {
      toast.error(err?.message || 'Erreur lors de la génération');
    } finally {
      setGenerating(false);
    }
  }

  async function handleClearStatus() {
    setClearingStatus(true);
    try {
      await (clearLeadEmailSent as any)({ identifier });
      toast.success('Statut réinitialisé');
      refetchLogs();
      onSent();
    } catch (err: any) {
      toast.error(err?.message || 'Erreur');
    } finally {
      setClearingStatus(false);
    }
  }

  async function handleSubmit() {
    if (!to.trim()) { toast.error('Destinataire requis'); return; }
    if (!subject.trim()) { toast.error('Objet requis'); return; }
    setSending(true);
    try {
      await (saveLeadEmailDraft as any)({ identifier, to: to.trim(), cc: cc.trim() || '', subject: subject.trim(), body });
      await (sendProspectEmail as any)({
        identifier,
        to: to.trim(),
        cc: cc.trim() || null,
        subject: subject.trim(),
        body,
      });
      toast.success('Courriel envoyé');
      onSent();
      onClose();
    } catch (err: any) {
      toast.error(err?.message || "Erreur lors de l'envoi");
    } finally {
      setSending(false);
    }
  }

  return (
    <div className='space-y-4'>
      <div className='flex items-center justify-between gap-2 -mt-1 -mb-1'>
        <div className='flex items-center gap-1.5 min-w-0'>
          {emailTemplates.length > 0 && (
            <select
              className='input w-auto py-1 text-xs max-w-[180px]'
              value={templateId}
              onChange={e => {
                setTemplateId(e.target.value);
                if (e.target.value) handleApplyTemplate(e.target.value);
              }}
              disabled={sending || generating || savingDraft}
              title='Modèle de courriel à utiliser'
            >
              <option value=''>Aucun modèle</option>
              {emailTemplates.map(t => (
                <option key={t.id} value={t.id}>{t.name}</option>
              ))}
            </select>
          )}
          <button
            className={`btn-ghost px-2 py-1 flex items-center gap-1.5 text-xs ${
              fromTemplate
                ? 'text-emerald-700 bg-emerald-50 border border-emerald-200 rounded-full'
                : emailTemplates.length ? 'text-emerald-600' : 'text-muted'
            }`}
            onClick={() => handleApplyTemplate()}
            disabled={sending || generating || savingDraft || !templateId}
            title={fromTemplate ? 'Modèle appliqué — cliquer pour réappliquer' : 'Appliquer le modèle sélectionné'}
          >
            <LuFilePen size={13} />
            {fromTemplate ? 'Appliqué' : 'Appliquer'}
          </button>
        </div>
        <button
          className='btn-ghost px-2 py-1 text-violet-500 flex items-center gap-1.5 text-xs'
          onClick={handleGenerate}
          disabled={sending || generating || savingDraft}
          title={generating ? 'Génération…' : 'Rédiger avec l\u2019IA'}
        >
          {generating ? <LuLoader size={13} className='animate-spin' /> : <LuWand size={13} />}
          {generating ? 'Génération…' : 'Rédiger avec l\u2019IA'}
        </button>
      </div>
      {!(lead as any).email && (
        <div className='text-xs bg-amber-50 border border-amber-200 rounded-md px-3 py-2 text-amber-700'>
          Aucun courriel trouvé pour ce prospect. Vous pouvez en saisir un manuellement.
        </div>
      )}
      {!emailCanSend && (
        <div className='text-xs bg-amber-50 border border-amber-200 rounded-md px-3 py-2 text-amber-700'>
          {emailReason}
        </div>
      )}

      <div>
        <label className='label'>À (destinataire)</label>
        <input type='email' className='input' value={to} onChange={e => setTo(e.target.value)} placeholder='contact@entreprise.com' />
      </div>
      <div>
        <label className='label'>Cc</label>
        <input type='text' className='input' value={cc} onChange={e => setCc(e.target.value)} placeholder='vous@entreprise.com' />
        <span className='text-xs text-muted mt-1 block'>Séparez plusieurs adresses par des virgules.</span>
      </div>
      {(company as any)?.email ? (
        <div className='text-xs text-muted flex items-start gap-1.5'>
          <LuRotateCcw size={13} className='mt-0.5 shrink-0' />
          <span>Les réponses du prospect arriveront à <strong className='font-medium'>{(company as any).email}</strong>.</span>
        </div>
      ) : (
        <div className='text-xs bg-amber-50 border border-amber-200 rounded-md px-3 py-2 text-amber-700'>
          Aucun courriel n’est configuré pour votre entreprise : les réponses du prospect seront perdues. Ajoutez-en un dans Paramètres.
        </div>
      )}
      <div>
        <label className='label'>Objet</label>
        <MagicInput type='text' className='input' value={subject} onChange={e => setSubject(e.target.value)} />
      </div>
      <div>
        <label className='label'>Message</label>
        <MagicTextarea className='input min-h-[160px] resize-y' value={body} onChange={e => setBody(e.target.value)} />
      </div>
      <div className='flex justify-between items-center pt-2'>
        <div className='flex gap-1'>
          <button
            className='btn-ghost p-2'
            onClick={handleSaveDraft}
            disabled={sending || savingDraft || clearingStatus || generating}
            title={savingDraft ? 'Enregistrement…' : 'Enregistrer brouillon'}
          >
            <LuSave size={16} />
          </button>
          {(lead as any).hasEmailSent && (
            <button
              className='btn-ghost p-2 text-success'
              onClick={handleClearStatus}
              disabled={sending || clearingStatus}
              title='Réinitialiser le statut envoyé'
            >
              <LuRotateCcw size={16} />
            </button>
          )}
        </div>
        <div className='flex gap-2'>
          <button className='btn-secondary' onClick={onClose} disabled={sending}>Annuler</button>
          <button
            className='btn-primary gap-1.5 flex items-center'
            onClick={handleSubmit}
            disabled={sending || !emailCanSend}
            title={!emailCanSend ? (emailReason ?? '') : undefined}
          >
            <LuSend size={14} />
            {sending ? 'Envoi…' : (lead as any).hasEmailSent ? 'Réenvoyer' : 'Envoyer'}
          </button>
        </div>
      </div>

      {(sentLogs as any[]).length > 0 && (
        <div className='border-t border-line pt-3'>
          <div className='text-xs font-medium text-muted mb-2 flex items-center gap-1.5'>
            <LuClock size={13} />
            Envois précédents ({(sentLogs as any[]).length})
          </div>
          <div className='space-y-1'>
            {(sentLogs as any[]).map((log: any) => {
              const open = expandedLogId === log.id;
              return (
                <div key={log.id} className='border border-line rounded-md overflow-hidden'>
                  <button
                    className='w-full flex items-center gap-2 px-2.5 py-2 text-left hover:bg-canvas-100'
                    onClick={() => setExpandedLogId(open ? null : log.id)}
                  >
                    {open ? <LuChevronDown size={13} className='shrink-0 text-muted' /> : <LuChevronRight size={13} className='shrink-0 text-muted' />}
                    <span className='text-xs font-medium truncate flex-1'>{log.subject}</span>
                    <span className='text-xs text-muted shrink-0'>{formatMontrealTime(log.createdAt)}</span>
                  </button>
                  {open && (
                    <div className='px-3 py-2.5 bg-canvas-100 border-t border-line space-y-2'>
                      <dl className='text-xs space-y-1'>
                        <EmailPreviewRow
                          label='De'
                          value={log.fromEmail ? `${log.fromName || 'Gestia'} <${log.fromEmail}>` : (log.fromName || 'Gestia')}
                        />
                        <EmailPreviewRow label='À' value={log.to} />
                        {log.cc && <EmailPreviewRow label='Cc' value={log.cc} />}
                        <EmailPreviewRow label='Répondre à' value={log.replyTo || '— (réponses perdues)'} />
                        <EmailPreviewRow label='Objet' value={log.subject} />
                      </dl>
                      <div className='text-xs whitespace-pre-wrap bg-white border border-line rounded p-2.5 max-h-64 overflow-y-auto'>
                        {log.body || <span className='text-muted italic'>Corps non enregistré (envoyé avant l’ajout de l’aperçu).</span>}
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

function EmailPreviewRow({ label, value }: { label: string; value: string }) {
  return (
    <div className='flex gap-2'>
      <dt className='text-muted shrink-0 w-24'>{label}</dt>
      <dd className='flex-1 break-words'>{value}</dd>
    </div>
  );
}

// ─── Prospect SMS modal ──────────────────────────────────────────────────────

// Delivery state reported by Telnyx via webhook. 'queued' is our own optimistic
// value written at send time, before the first receipt arrives.
const SMS_STATUS_LABELS: Record<string, { label: string; className: string }> = {
  queued: { label: 'en attente', className: 'text-muted' },
  sending: { label: 'envoi…', className: 'text-muted' },
  sent: { label: 'envoyé', className: 'text-muted' },
  delivered: { label: 'livré', className: 'text-success' },
  sending_failed: { label: 'échec envoi', className: 'text-danger' },
  delivery_failed: { label: 'non livré', className: 'text-danger' },
  delivery_unconfirmed: { label: 'non confirmé', className: 'text-amber-600' },
  undelivered: { label: 'non livré', className: 'text-danger' },
  expired: { label: 'expiré', className: 'text-danger' },
};

function SmsStatusBadge({ status, errorCode }: { status?: string | null; errorCode?: string | null }) {
  if (!status) return null;
  const meta = SMS_STATUS_LABELS[status] ?? { label: status, className: 'text-muted' };
  return (
    <span className={meta.className} title={errorCode ? `Code Telnyx ${errorCode}` : undefined}>
      · {meta.label}
    </span>
  );
}

function ProspectSmsModal({ lead, searchTitle, onClose, onSent }: { lead: Lead; searchTitle: string; onClose: () => void; onSent: () => void }) {
  const identifier = (lead as any).placeId ?? lead.id;
  const { data: company } = useQuery(getCurrentCompany);
  const { data: templatesData } = useQuery(
    // @ts-ignore -- generated by Wasp on next restart
    getProspectTemplates,
    { searchId: lead.searchId },
  );
  const { data: sentLogs = [], refetch: refetchLogs } = useQuery(
    // @ts-ignore -- generated by Wasp on next restart
    getLeadSmsLogs,
    { identifier },
  );
  const smsTemplates = useMemo(
    () => templatesFor((templatesData as any[]) ?? [], 'sms'),
    [templatesData],
  );

  const { canSend: smsCanSend, reason: smsReason } = useSmsCapability();
  const [to, setTo] = useState<string>((lead as any).phone ?? '');
  const [text, setText] = useState('');
  const [templateId, setTemplateId] = useState('');
  const [sending, setSending] = useState(false);
  const [clearing, setClearing] = useState(false);
  const [generating, setGenerating] = useState(false);
  const [initialized, setInitialized] = useState(false);

  const senderName = (company as any)?.senderName ?? '';

  // Preload the model mapped to this lead's status.
  useEffect(() => {
    if (initialized || company === undefined || templatesData === undefined) return;
    const tmpl = pickTemplateForStatus(templatesData as any[], 'sms', (lead as any).status);
    setTemplateId(tmpl?.id ?? '');
    if (tmpl?.body) {
      setText(resolveTemplateVars(tmpl.body, lead, company, senderName, searchTitle));
    }
    setInitialized(true);
  }, [company, templatesData, initialized]);

  // Opening the thread counts as reading it; clears the reply badge in the list.
  const markedRead = useRef(false);
  useEffect(() => {
    if (markedRead.current || !(lead as any).smsUnreadCount) return;
    markedRead.current = true;
    (markLeadSmsRead as any)({ identifier })
      .then(() => { refetchLogs(); onSent(); })
      .catch(() => { markedRead.current = false; });
  }, [identifier]);

  function applyTemplate(id?: string) {
    const tmpl = smsTemplates.find(t => t.id === (id ?? templateId));
    if (!tmpl?.body) {
      toast.error('Aucun modèle SMS pour cette prospection');
      return;
    }
    setText(resolveTemplateVars(tmpl.body, lead, company, senderName, searchTitle));
  }

  async function handleGenerate() {
    setGenerating(true);
    try {
      // The generator writes a model with {{variables}}; they are resolved right
      // away since this text goes to one specific prospect.
      const result = await (generateProspectEmailTemplate as any)({
        searchId: lead.searchId,
        channel: 'sms',
        currentBody: text.trim() || null,
      });
      if (result.body) {
        setText(resolveTemplateVars(result.body, lead, company, senderName, searchTitle));
      }
      toast.success('Message généré');
    } catch (err: any) {
      toast.error(err?.message || 'Erreur lors de la génération');
    } finally {
      setGenerating(false);
    }
  }

  async function handleSend() {
    if (!to.trim()) { toast.error('Numéro requis'); return; }
    if (!text.trim()) { toast.error('Message requis'); return; }
    setSending(true);
    try {
      await (sendProspectSms as any)({ identifier, leadId: lead.id, to: to.trim(), body: text });
      toast.success('SMS envoyé');
      refetchLogs();
      onSent();
      onClose();
    } catch (err: any) {
      toast.error(err?.message || "Erreur lors de l'envoi");
    } finally {
      setSending(false);
    }
  }

  async function handleClearStatus() {
    setClearing(true);
    try {
      await (clearLeadSmsSent as any)({ identifier });
      toast.success('Statut réinitialisé');
      refetchLogs();
      onSent();
    } catch (err: any) {
      toast.error(err?.message || 'Erreur');
    } finally {
      setClearing(false);
    }
  }

  const counts = smsSegments(text);

  return (
    <div className='space-y-4'>
      <div className='flex items-center justify-between gap-2 -mt-1 -mb-1'>
        <div className='flex items-center gap-1.5 min-w-0'>
          {smsTemplates.length > 0 && (
            <select
              className='input w-auto py-1 text-xs max-w-[180px]'
              value={templateId}
              onChange={e => {
                setTemplateId(e.target.value);
                if (e.target.value) applyTemplate(e.target.value);
              }}
              disabled={sending || generating}
              title='Modèle de SMS à utiliser'
            >
              <option value=''>Aucun modèle</option>
              {smsTemplates.map(t => (
                <option key={t.id} value={t.id}>{t.name}</option>
              ))}
            </select>
          )}
          <button
            className='btn-ghost px-2 py-1 flex items-center gap-1.5 text-xs text-emerald-600'
            onClick={() => applyTemplate()}
            disabled={sending || generating || !templateId}
            title='Appliquer le modèle sélectionné'
          >
            <LuFilePen size={13} />
            Appliquer
          </button>
        </div>
        <button
          className='btn-ghost px-2 py-1 text-violet-500 flex items-center gap-1.5 text-xs'
          onClick={handleGenerate}
          disabled={sending || generating}
          title={generating ? 'Génération…' : 'Rédiger avec l’IA'}
        >
          {generating ? <LuLoader size={13} className='animate-spin' /> : <LuWand size={13} />}
          {generating ? 'Génération…' : 'Rédiger avec l’IA'}
        </button>
      </div>

      {!smsCanSend && (
        <div className='text-xs bg-amber-50 border border-amber-200 rounded-md px-3 py-2 text-amber-700'>
          {smsReason}
        </div>
      )}

      {!(lead as any).phone && (
        <div className='text-xs bg-amber-50 border border-amber-200 rounded-md px-3 py-2 text-amber-700'>
          Aucun téléphone trouvé pour ce prospect. Vous pouvez en saisir un manuellement.
        </div>
      )}

      <div>
        <label className='label'>À (numéro)</label>
        <input
          type='tel'
          className='input'
          value={to}
          onChange={e => setTo(e.target.value)}
          placeholder='(514) 555-0100'
        />
        <span className='text-xs text-muted mt-1 block'>
          Les numéros à 10 chiffres sont envoyés en +1 (Amérique du Nord).
        </span>
      </div>

      <div>
        <label className='label'>Message</label>
        <MagicTextarea
          className='input min-h-[120px] resize-y'
          value={text}
          onChange={e => setText(e.target.value)}
          placeholder={`Bonjour, ici ${(company as any)?.name ?? 'notre entreprise'}…`}
        />
        <div className='text-xs text-muted mt-1 flex items-center gap-1.5'>
          <span>{counts.chars} caractère(s) · {counts.segments} SMS</span>
          {counts.unicode && <span className='text-amber-600'>caractères spéciaux — limite 70 par SMS</span>}
        </div>
      </div>

      <div className='flex justify-between items-center pt-2'>
        <div className='flex gap-1'>
          {(lead as any).hasSmsSent && (
            <button
              className='btn-ghost p-2 text-success'
              onClick={handleClearStatus}
              disabled={sending || clearing}
              title='Réinitialiser le statut envoyé'
            >
              <LuRotateCcw size={16} />
            </button>
          )}
        </div>
        <div className='flex gap-2'>
          <button className='btn-secondary' onClick={onClose} disabled={sending}>Annuler</button>
          <button
            className='btn-primary gap-1.5 flex items-center'
            onClick={handleSend}
            disabled={sending || !smsCanSend}
            title={!smsCanSend ? (smsReason ?? '') : undefined}
          >
            <LuMessageSquare size={14} />
            {sending ? 'Envoi…' : (lead as any).hasSmsSent ? 'Renvoyer' : 'Envoyer'}
          </button>
        </div>
      </div>

      {(sentLogs as any[]).length > 0 && (
        <div className='border-t border-line pt-3'>
          <div className='text-xs font-medium text-muted mb-2 flex items-center gap-1.5'>
            <LuClock size={13} />
            Conversation ({(sentLogs as any[]).length})
          </div>
          <div className='space-y-1.5 max-h-[280px] overflow-y-auto pr-1'>
            {(sentLogs as any[]).map((log: any) => {
              const inbound = log.direction === 'inbound';
              return (
                <div
                  key={log.id}
                  className={`rounded-md px-2.5 py-2 border ${
                    inbound
                      ? 'border-accent-100 bg-accent-50 mr-6'
                      : 'border-line ml-6'
                  }`}
                >
                  <div className='flex items-center gap-2 text-xs text-muted'>
                    <span className='font-medium text-ink'>
                      {inbound ? `Réponse — ${log.fromNumber}` : log.to}
                    </span>
                    {!inbound && <SmsStatusBadge status={log.status} errorCode={log.errorCode} />}
                    <span className='ml-auto shrink-0'>{formatMontrealTime(log.createdAt)}</span>
                  </div>
                  <div className='text-xs whitespace-pre-wrap mt-1'>{log.body}</div>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

function NoteModal({ lead, onClose }: { lead: Lead; onClose: () => void }) {
  const identifier = (lead as any).placeId ?? lead.id;
  const { data: notes = [], refetch } = useQuery(getLeadNotes, { identifier });
  const [text, setText] = useState('');
  const [saving, setSaving] = useState(false);
  const [deletingId, setDeletingId] = useState<string | null>(null);

  async function handleAdd(e: React.FormEvent) {
    e.preventDefault();
    if (!text.trim()) return;
    setSaving(true);
    try {
      await addLeadNote({ leadId: lead.id, text });
      setText('');
      refetch();
    } catch {
      toast.error('Erreur lors de l\'ajout');
    } finally {
      setSaving(false);
    }
  }

  async function handleDelete(id: string) {
    setDeletingId(id);
    try {
      await deleteLeadNote({ id });
      refetch();
    } catch {
      toast.error('Erreur lors de la suppression');
    } finally {
      setDeletingId(null);
    }
  }

  return (
    <NoteThread
      notes={notes as any[]}
      text={text}
      setText={setText}
      onSubmit={handleAdd}
      onDelete={handleDelete}
      saving={saving}
      deletingId={deletingId}
    />
  );
}

// ─── Manage statuses modal ────────────────────────────────────────────────────

function ManageStatusesModal({
  configs,
  onRefresh,
  onClose,
}: {
  configs: LeadStatusConfig[];
  onRefresh: () => void;
  onClose: () => void;
}) {
  const unknownEntry = configs.find(c => c.key === 'unknown');

  // Local ordered list for instant visual feedback
  const [ordered, setOrdered] = useState(() => configs.filter(c => c.key !== 'unknown'));
  useEffect(() => {
    setOrdered(configs.filter(c => c.key !== 'unknown'));
  }, [configs]);

  const [editId, setEditId] = useState<string | null>(null);
  const [editLabel, setEditLabel] = useState('');
  const [editColor, setEditColor] = useState('');
  const [newLabel, setNewLabel] = useState('');
  const [newColor, setNewColor] = useState('#6366f1');
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const dragIndex = useRef<number | null>(null);
  const [dragOverIndex, setDragOverIndex] = useState<number | null>(null);

  function startEdit(c: LeadStatusConfig) {
    setEditId(c.id);
    setEditLabel(c.label);
    setEditColor(c.color);
    setConfirmDeleteId(null);
  }

  async function saveEdit() {
    if (!editId) return;
    setSaving(true);
    try {
      await updateLeadStatusConfig({ id: editId, label: editLabel, color: editColor });
      onRefresh();
      setEditId(null);
    } catch {
      toast.error('Erreur lors de la sauvegarde');
    } finally {
      setSaving(false);
    }
  }

  async function handleDelete(id: string) {
    setSaving(true);
    try {
      await deleteLeadStatusConfig({ id });
      onRefresh();
      setConfirmDeleteId(null);
    } catch (e: any) {
      toast.error(e?.message ?? 'Erreur lors de la suppression');
    } finally {
      setSaving(false);
    }
  }

  async function handleCreate(e: React.FormEvent) {
    e.preventDefault();
    if (!newLabel.trim()) return;
    setSaving(true);
    try {
      await createLeadStatusConfig({
        key: newLabel,
        label: newLabel.trim(),
        color: newColor,
        order: ordered.length,
      });
      setNewLabel('');
      setNewColor('#6366f1');
      onRefresh();
    } catch (e: any) {
      toast.error(e?.message ?? 'Erreur lors de la création');
    } finally {
      setSaving(false);
    }
  }

  function handleDragStart(index: number) {
    dragIndex.current = index;
  }

  function handleDragEnter(index: number) {
    if (dragIndex.current === null || dragIndex.current === index) return;
    setDragOverIndex(index);
    const newList = [...ordered];
    const [moved] = newList.splice(dragIndex.current, 1);
    newList.splice(index, 0, moved);
    dragIndex.current = index;
    setOrdered(newList);
  }

  async function handleDragEnd() {
    setDragOverIndex(null);
    dragIndex.current = null;
    const items = ordered.map((c, i) => ({ id: c.id, order: i }));
    try {
      await reorderLeadStatusConfigs({ items });
      onRefresh();
    } catch {
      toast.error('Erreur lors du réordonnancement');
    }
  }

  return (
    <div className='space-y-4'>
      <div className='flex items-start gap-2.5 rounded-xl border border-amber-200 bg-amber-50 px-3.5 py-3 text-sm text-amber-800'>
        <LuTriangleAlert size={15} className='shrink-0 mt-0.5' />
        <p>Toute modification (renommage, réordonnancement, suppression) s'applique immédiatement à tous les prospects existants.</p>
      </div>
      <div className='space-y-2'>
      {ordered.map((c, index) => {
        const isSystem = c.key === 'nouveau' || c.key === 'qualifie';
        return (
        <div
          key={c.id}
          draggable={!isSystem}
          onDragStart={() => !isSystem && handleDragStart(index)}
          onDragEnter={() => !isSystem && handleDragEnter(index)}
          onDragEnd={!isSystem ? handleDragEnd : undefined}
          onDragOver={e => e.preventDefault()}
          className={`flex items-center gap-2 p-2.5 rounded-xl border transition-colors ${
            dragOverIndex === index ? 'border-accent-400 bg-accent-50' : 'border-line'
          } ${isSystem ? 'opacity-70' : ''}`}
        >
          {editId === c.id ? (
            <>
              <input
                type='color'
                value={editColor}
                onChange={e => setEditColor(e.target.value)}
                className='w-7 h-7 rounded cursor-pointer border border-line shrink-0'
              />
              <input
                className='input flex-1 py-1.5 text-sm'
                value={editLabel}
                onChange={e => setEditLabel(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && saveEdit()}
                autoFocus
              />
              <button className='btn-primary py-1 px-2.5 text-xs' onClick={saveEdit} disabled={saving}>
                OK
              </button>
              <button className='btn-secondary py-1 px-2.5 text-xs' onClick={() => setEditId(null)}>
                Annuler
              </button>
            </>
          ) : (
            <>
              {/* Drag handle */}
              <span className='text-muted cursor-grab active:cursor-grabbing shrink-0' title='Glisser pour réordonner'>
                <LuGripVertical size={16} />
              </span>
              <div className='w-4 h-4 rounded-full shrink-0' style={{ backgroundColor: c.color }} />
              <span className='flex-1 text-sm font-medium'>{c.label}</span>
              <span className='text-xs text-muted font-mono bg-canvas px-1.5 py-0.5 rounded'>{c.key}</span>
              {isSystem ? (
                <>
                  <span className='shrink-0'><LuLock size={13} className='text-muted' /></span>
                  <span className='text-xs text-muted'>Verrouillé</span>
                </>
              ) : confirmDeleteId === c.id ? (
                <div className='flex items-center gap-1.5'>
                  <span className='text-xs text-red-600 font-medium'>Supprimer ?</span>
                  <button
                    className='text-xs text-red-600 font-semibold hover:underline'
                    onClick={() => handleDelete(c.id)}
                    disabled={saving}
                  >
                    Oui
                  </button>
                  <button
                    className='text-xs text-muted hover:underline'
                    onClick={() => setConfirmDeleteId(null)}
                  >
                    Non
                  </button>
                </div>
              ) : (
                <>
                  <IconBtn title='Modifier' onClick={() => startEdit(c)}>
                    <LuPencil size={14} />
                  </IconBtn>
                  <IconBtn title='Supprimer' variant='danger' onClick={() => setConfirmDeleteId(c.id)}>
                    <LuTrash2 size={14} />
                  </IconBtn>
                </>
              )}
            </>
          )}
        </div>
        );
      })}

      {/* Locked unknown row */}
      {unknownEntry && (
        <div className='flex items-center gap-2 p-2.5 rounded-xl border border-line bg-canvas opacity-60'>
          <span className='shrink-0'><LuLock size={14} className='text-muted' /></span>
          <div className='w-4 h-4 rounded-full shrink-0' style={{ backgroundColor: unknownEntry.color }} />
          <span className='flex-1 text-sm font-medium'>{unknownEntry.label}</span>
          <span className='text-xs text-muted font-mono bg-canvas px-1.5 py-0.5 rounded'>{unknownEntry.key}</span>
          <span className='text-xs text-muted'>Verrouillé</span>
        </div>
      )}
      </div>

      <hr className='border-line' />

      <form onSubmit={handleCreate} className='flex items-center gap-2'>
        <input
          type='color'
          value={newColor}
          onChange={e => setNewColor(e.target.value)}
          className='w-7 h-7 rounded cursor-pointer border border-line shrink-0'
          title='Couleur du statut'
        />
        <input
          className='input flex-1'
          placeholder='Ex : En négociation'
          value={newLabel}
          onChange={e => setNewLabel(e.target.value)}
          required
        />
        <button type='submit' className='btn-primary gap-1.5 shrink-0' disabled={saving || !newLabel.trim()}>
          <LuPlus size={14} />
          Ajouter
        </button>
      </form>
      <p className='text-xs text-muted'>La clé (identifiant interne) est générée automatiquement depuis le nom.</p>
    </div>
  );
}

// ─── Share modal ──────────────────────────────────────────────────────────────

function ShareProspectModal({ searchId, onClose }: { searchId: string; onClose: () => void }) {
  const { data: shareToken, isLoading, refetch } = useQuery(
    // @ts-ignore
    getLeadShareToken,
    { searchId },
    { retry: false },
  );
  const [creating, setCreating] = useState(false);
  const [revoking, setRevoking] = useState(false);
  const [copied, setCopied] = useState(false);
  const { ask, Dialog } = useConfirm();

  const baseUrl = typeof window !== 'undefined' ? `${window.location.origin}/prospect-portail/` : '/prospect-portail/';
  const tokenData = shareToken as any;
  const isActive = tokenData && !tokenData.isRevoked;

  async function handleCreate() {
    setCreating(true);
    try {
      await (createLeadShareToken as any)({ searchId });
      toast.success('Lien créé');
      refetch();
    } catch (e: any) {
      toast.error(e?.message || 'Erreur');
    } finally {
      setCreating(false);
    }
  }

  async function handleRegenerate() {
    if (!(await ask('Régénérer le lien ? L\'ancien lien sera immédiatement désactivé.'))) return;
    setCreating(true);
    try {
      await (createLeadShareToken as any)({ searchId });
      toast.success('Nouveau lien généré');
      setCopied(false);
      refetch();
    } catch (e: any) {
      toast.error(e?.message || 'Erreur');
    } finally {
      setCreating(false);
    }
  }

  async function handleRevoke() {
    if (!(await ask('Désactiver ce lien ? L\'employé ne pourra plus y accéder.'))) return;
    setRevoking(true);
    try {
      await (revokeLeadShareToken as any)({ searchId });
      toast.success('Lien désactivé');
      refetch();
    } catch (e: any) {
      toast.error(e?.message || 'Erreur');
    } finally {
      setRevoking(false);
    }
  }

  function copyLink() {
    navigator.clipboard.writeText(`${baseUrl}${tokenData.token}`);
    setCopied(true);
    toast.success('Lien copié dans le presse-papiers');
    setTimeout(() => setCopied(false), 2000);
  }

  return (
    <div className='flex flex-col gap-5'>
      {Dialog}
      <div className='card p-4 bg-blue-50 border-blue-200'>
        <p className='text-sm text-muted leading-relaxed'>
          Partagez ce lien avec un employé pour lui permettre d'accéder à la liste des prospects, déplacer les cartes, modifier les informations et supprimer des prospects — sans compte ni connexion.
        </p>
      </div>

      {isLoading ? (
        <div className='flex items-center justify-center py-6'>
          <LuLoader size={20} className='animate-spin text-muted' />
        </div>
      ) : isActive ? (
        <div className='space-y-3'>
          <div className='flex items-center gap-2'>
            <div className='flex-1 min-w-0'>
              <p className='text-xs font-mono text-muted truncate bg-canvas border border-line rounded-lg px-3 py-2'>
                {baseUrl}{tokenData.token}
              </p>
              {tokenData.lastUsedAt && (
                <p className='text-xs text-muted mt-1'>
                  Dernière utilisation : {new Date(tokenData.lastUsedAt).toLocaleDateString('fr-CA', { day: 'numeric', month: 'short', year: 'numeric' })}
                </p>
              )}
            </div>
          </div>
          <div className='flex flex-wrap gap-2'>
            <button
              className={`btn-primary flex items-center gap-1.5 text-sm ${copied ? 'opacity-80' : ''}`}
              onClick={copyLink}
            >
              {copied ? <LuCheck size={14} /> : <LuCopy size={14} />}
              {copied ? 'Copié !' : 'Copier le lien'}
            </button>
            <a
              href={`/prospect-portail/${tokenData.token}`}
              target='_blank'
              rel='noreferrer'
              className='btn-secondary flex items-center gap-1.5 text-sm'
            >
              <LuExternalLink size={14} />
              Ouvrir
            </a>
            <button
              className='btn-secondary flex items-center gap-1.5 text-sm'
              onClick={handleRegenerate}
              disabled={creating}
            >
              {creating ? <LuLoader size={14} className='animate-spin' /> : <LuRefreshCcw size={14} />}
              Régénérer
            </button>
            <button
              className='btn-ghost text-red-600 hover:bg-red-50 flex items-center gap-1.5 text-sm'
              onClick={handleRevoke}
              disabled={revoking}
            >
              {revoking ? <LuLoader size={14} className='animate-spin' /> : <LuX size={14} />}
              Désactiver
            </button>
          </div>
        </div>
      ) : (
        <div className='space-y-3'>
          {tokenData?.isRevoked && (
            <div className='text-sm text-muted bg-canvas border border-line rounded-lg px-3 py-2'>
              Le lien précédent est désactivé.
            </div>
          )}
          <button
            className='btn-primary flex items-center gap-1.5'
            onClick={handleCreate}
            disabled={creating}
          >
            {creating ? <LuLoader size={14} className='animate-spin' /> : <LuLink size={14} />}
            {creating ? 'Génération…' : 'Générer un lien de partage'}
          </button>
        </div>
      )}

      <div className='flex justify-end pt-1 border-t border-line'>
        <button className='btn-secondary' onClick={onClose}>Fermer</button>
      </div>
    </div>
  );
}

// ─── Fetch more prospects (Google Maps, same criteria) ───────────────────────
// Reached from the search details modal and from the Nouveau column header.

function FetchMoreLeadsModal({
  open,
  searchId,
  searchFilters,
  searchTitle,
  searchPurpose,
  onClose,
  onAdded,
  onBusyChange,
}: {
  open: boolean;
  searchId: string;
  searchFilters: { businessType?: string; city?: string; province?: string; radius?: number; minRating?: number; requireWebsite?: boolean; maxResults?: number; language?: string };
  searchTitle?: string;
  searchPurpose?: string;
  onClose: () => void;
  /** Called after new prospects landed, so the board can refresh. */
  onAdded: () => void;
  /** Mirrors the in-flight state so the board can spin its own trigger. */
  onBusyChange?: (busy: boolean) => void;
}) {
  const [fetchingMore, setFetchingMore] = useState(false);
  const [fetchStatus, setFetchStatus] = useState<string>('');
  const [fetchExhausted, setFetchExhausted] = useState<{ nextExpandedRadiusKm: number; currentRadiusKm: number } | null>(null);

  async function handleFetchMore(radiusOverride?: number) {
    setFetchingMore(true);
    onBusyChange?.(true);
    setFetchExhausted(null);
    const currentKm = (radiusOverride ?? searchFilters.radius ?? 10000) / 1000;
    setFetchStatus(radiusOverride
      ? `Élargissement à ${currentKm} km en cours…`
      : `Recherche dans un rayon de ${currentKm} km…`);
    try {
      const result = await (fetchMoreLeads as any)({ searchId, radiusOverride });
      if (result.exhausted) {
        const canExpand = result.nextExpandedRadiusKm > currentKm;
        if (canExpand) {
          setFetchExhausted({ nextExpandedRadiusKm: result.nextExpandedRadiusKm, currentRadiusKm: currentKm });
        } else {
          onClose();
          toast('Aucun nouveau prospect trouvé, même au rayon maximum (50 km)', { icon: 'ℹ️' });
        }
      } else {
        onClose();
        setFetchExhausted(null);
        toast.success(`${result.added} nouveau(x) prospect(s) ajouté(s)`);
        onAdded();
      }
    } catch (e: any) {
      toast.error(e?.message ?? 'Erreur lors de la recherche');
    } finally {
      setFetchingMore(false);
      onBusyChange?.(false);
      setFetchStatus('');
    }
  }


  return (
        <Modal
      open={open}
      title='Chercher plus de prospects'
      onClose={() => { if (!fetchingMore) { setFetchExhausted(null); onClose(); } }}
    >
      <div className='space-y-4'>
        <p className='text-sm text-muted'>
          Une nouvelle recherche Google Maps sera effectuée avec les mêmes critères. Si tous les résultats du rayon actuel sont déjà dans la liste, le rayon sera automatiquement élargi pour trouver de nouveaux prospects.
        </p>
        {fetchingMore && (
          <div className='flex items-center gap-3 text-sm text-accent-700 bg-accent-50 border border-accent-200 rounded-xl px-4 py-3'>
            <LuLoader size={15} className='animate-spin shrink-0' />
            <span>{fetchStatus || 'Recherche en cours…'}</span>
          </div>
        )}
        {fetchExhausted && !fetchingMore && (
          <div className='rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800 space-y-2'>
            <p className='font-medium'>Aucun nouveau prospect dans un rayon de {fetchExhausted.currentRadiusKm} km.</p>
            <p>Voulez-vous élargir la zone de recherche à <strong>{fetchExhausted.nextExpandedRadiusKm} km</strong> ?</p>
          </div>
        )}
        <div className='rounded-xl border border-line bg-canvas p-3.5 space-y-2 text-sm'>
            <div className='flex justify-between gap-2'>
              <span className='text-muted'>Nom de la recherche</span>
              <span className='font-medium text-right'>{searchTitle || <span className='text-muted italic'>Peu importe</span>}</span>
            </div>
            <div className='flex justify-between gap-2'>
              <span className='text-muted'>Objectif</span>
              <span className='font-medium text-right'>{searchPurpose || <span className='text-muted italic'>Peu importe</span>}</span>
            </div>
            <hr className='border-line' />
            <div className='flex justify-between gap-2'>
              <span className='text-muted'>Type d'entreprise</span>
              <span className='font-medium text-right'>{searchFilters.businessType || <span className='text-muted italic'>Peu importe</span>}</span>
            </div>
            <div className='flex justify-between gap-2'>
              <span className='text-muted'>Ville</span>
              <span className='font-medium'>
                {searchFilters.city
                  ? `${searchFilters.city}${searchFilters.province ? `, ${searchFilters.province}` : ''}`
                  : <span className='text-muted italic'>Peu importe</span>}
              </span>
            </div>
            <div className='flex justify-between gap-2'>
              <span className='text-muted'>Rayon</span>
              <span className='font-medium'>
                {searchFilters.radius != null ? `${(searchFilters.radius / 1000).toFixed(0)} km` : <span className='text-muted italic'>Peu importe</span>}
              </span>
            </div>
            <div className='flex justify-between gap-2'>
              <span className='text-muted'>Nombre de résultats</span>
              <span className='font-medium'>{searchFilters.maxResults ?? <span className='text-muted italic'>Peu importe</span>}</span>
            </div>
            <div className='flex justify-between gap-2'>
              <span className='text-muted'>Note minimale</span>
              <span className='font-medium'>
                {searchFilters.minRating != null && searchFilters.minRating > 0
                  ? `≥ ${searchFilters.minRating} ★`
                  : <span className='text-muted italic'>Peu importe</span>}
              </span>
            </div>
            <div className='flex justify-between gap-2'>
              <span className='text-muted'>Langue</span>
              <span className='font-medium'>
                {searchFilters.language === 'fr' ? 'Français' : searchFilters.language === 'en' ? 'Anglais' : <span className='text-muted italic'>Peu importe</span>}
              </span>
            </div>
            <div className='flex justify-between gap-2'>
              <span className='text-muted'>Site web requis</span>
              <span className='font-medium'>{searchFilters.requireWebsite ? 'Oui' : 'Non'}</span>
            </div>
          </div>
        <div className='flex justify-end gap-2'>
          <button className='btn-secondary' onClick={() => { setFetchExhausted(null); onClose(); }} disabled={fetchingMore}>
            Annuler
          </button>
          {fetchExhausted ? (
            <button className='btn-primary gap-1.5' onClick={() => handleFetchMore(fetchExhausted.nextExpandedRadiusKm * 1000)} disabled={fetchingMore}>
              {fetchingMore ? <LuLoader size={14} className='animate-spin' /> : <LuPlus size={14} />}
              Élargir à {fetchExhausted.nextExpandedRadiusKm} km
            </button>
          ) : (
            <button className='btn-primary gap-1.5' onClick={() => handleFetchMore()} disabled={fetchingMore}>
              {fetchingMore ? <LuLoader size={14} className='animate-spin' /> : <LuPlus size={14} />}
              {fetchingMore ? 'Recherche…' : 'Lancer la recherche'}
            </button>
          )}
        </div>
      </div>
    </Modal>
  );
}

// ─── Leads kanban ─────────────────────────────────────────────────────────────

function LeadsKanban({
  leads,
  statusConfigs,
  searchId,
  searchFilters,
  searchTitle,
  searchPurpose,
  refetch,
  onNote,
  onEmail,
  onSms,
  onConvert,
  onOpenDetail,
  selectedLeadId,
  existingClientNames,
  searchQuery,
  setSearchQuery,
  activeFilters,
  setActiveFilters,
  onResetFilters,
  selectedIds,
  setSelectedIds,
  onToggleSelect,
  onBulkDelete,
  onAddLead,
  onFetchMore,
  fetchingMore,
}: {
  leads: Lead[];
  statusConfigs: LeadStatusConfig[];
  searchId: string;
  searchFilters: { businessType?: string; city?: string; province?: string; radius?: number; minRating?: number; requireWebsite?: boolean; maxResults?: number; language?: string };
  searchTitle?: string;
  searchPurpose?: string;
  refetch: () => void;
  onNote: (lead: Lead) => void;
  onEmail: (lead: Lead) => void;
  onSms: (lead: Lead) => void;
  onConvert: (lead: Lead) => void;
  onOpenDetail: (lead: Lead) => void;
  selectedLeadId: string | null;
  existingClientNames: Set<string>;
  searchQuery: string;
  setSearchQuery: (v: string) => void;
  activeFilters: Set<string>;
  setActiveFilters: (fn: (prev: Set<string>) => Set<string>) => void;
  onResetFilters: () => void;
  selectedIds: Set<string>;
  setSelectedIds: React.Dispatch<React.SetStateAction<Set<string>>>;
  onToggleSelect: (leadId: string) => void;
  /** Opens the bulk-delete confirmation for the given leads. */
  onBulkDelete: (leads: Lead[]) => void;
  /** Opens the manual "add a prospect" form (the + on the Nouveau column). */
  onAddLead: () => void;
  /** Opens the "search more on Google Maps" modal, owned by the board. */
  onFetchMore: () => void;
  fetchingMore: boolean;
}) {
  const onNoteRef = useRef(onNote);
  onNoteRef.current = onNote;
  const onEmailRef = useRef(onEmail);
  onEmailRef.current = onEmail;
  const onSmsRef = useRef(onSms);
  onSmsRef.current = onSms;
  const onConvertRef = useRef(onConvert);
  onConvertRef.current = onConvert;
  const onOpenDetailRef = useRef(onOpenDetail);
  onOpenDetailRef.current = onOpenDetail;
  const existingClientNamesRef = useRef(existingClientNames);
  existingClientNamesRef.current = existingClientNames;

  // Telnyx / SMTP not configured → the matching action is disabled everywhere,
  // with the reason surfaced as a tooltip rather than failing on click.
  const { canSend: smsCanSend, reason: smsReason } = useSmsCapability();
  const { canSend: emailCanSend, reason: emailReason } = useEmailCapability();

  async function updateStatus(leadId: string, newStatus: string) {
    await updateLead({ id: leadId, status: newStatus });
  }
  async function reorder(status: string, orderedIds: string[]) {
    await (reorderLeads as any)({ searchId, status, orderedIds });
  }
  function toggleFilter(key: string) {
    setActiveFilters(prev => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key); else next.add(key);
      return next;
    });
  }

  function getEmailDomain(email: string): string {
    return email.split('@')[1]?.toLowerCase() ?? '';
  }
  function getWebsiteDomain(url: string): string {
    try { return new URL(url.startsWith('http') ? url : `https://${url}`).hostname.replace(/^www\./, '').toLowerCase(); }
    catch { return url.toLowerCase().replace(/^www\./, ''); }
  }
  function emailMatchesDomain(lead: Lead): boolean {
    if (!lead.email || !lead.website) return true;
    const eDomain = getEmailDomain(lead.email);
    const wDomain = getWebsiteDomain(lead.website);
    return eDomain === wDomain || wDomain.endsWith(`.${eDomain}`) || eDomain.endsWith(`.${wDomain}`);
  }

  const filteredLeads = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    return leads.filter(l => {
      if (q && ![
        l.name, l.email, l.phone, l.website, l.address, l.category,
      ].some(v => v?.toLowerCase().includes(q))) return false;
      for (const f of activeFilters) {
        if (f === 'has_email' && !l.email) return false;
        if (f === 'no_email' && !!l.email) return false;
        if (f === 'no_website' && !!l.website) return false;
        if (f === 'email_mismatch' && (!l.email || !l.website || emailMatchesDomain(l))) return false;
      }
      return true;
    });
  }, [leads, activeFilters, searchQuery]);

  // Only the cards currently on the board can be acted on — the ones hidden by
  // the search box or the filter chips stay out of every bulk action.
  const selectedVisible = filteredLeads.filter(l => selectedIds.has(l.id));

  // Whole-column tick from a column header. The board passes the ids it has on
  // screen, so a filtered-out card is never swept in.
  function selectMany(leadIds: string[], selected: boolean) {
    setSelectedIds(prev => {
      const next = new Set(prev);
      leadIds.forEach(id => { if (selected) next.add(id); else next.delete(id); });
      return next;
    });
  }

  const cardActionsForLead = useCallback((lead: any): React.ReactNode => {
    const l = lead as Lead & { notes?: string | null };
    return (
      <div className='flex items-center gap-1'>
        {l.email && (
          <button
            className={`w-6 h-6 rounded flex items-center justify-center transition-colors relative ${
              !emailCanSend
                ? 'text-muted opacity-40 cursor-not-allowed'
                : `hover:bg-canvas ${(l as any).hasEmailSent ? 'text-success hover:text-emerald-700' : 'text-muted hover:text-ink'}`
            }`}
            disabled={!emailCanSend}
            title={
              !emailCanSend
                ? (emailReason ?? '')
                : (l as any).hasEmailSent ? 'Réenvoyer un courriel' : (l as any).hasEmailDraft ? 'Reprendre le brouillon' : 'Envoyer un courriel'
            }
            onClick={e => { e.stopPropagation(); onEmailRef.current(l); }}
          >
            <LuSend size={11} />
            {emailCanSend && (l as any).hasEmailDraft && !(l as any).hasEmailSent && (
              <span className='absolute -top-0.5 -right-0.5 w-1.5 h-1.5 rounded-full bg-amber-400 pointer-events-none' />
            )}
          </button>
        )}
        {l.phone && (
          <button
            className={`w-6 h-6 rounded flex items-center justify-center transition-colors relative ${
              !smsCanSend
                ? 'text-muted opacity-40 cursor-not-allowed'
                : `hover:bg-canvas ${(l as any).hasSmsSent ? 'text-success hover:text-emerald-700' : 'text-muted hover:text-ink'}`
            }`}
            disabled={!smsCanSend}
            title={
              !smsCanSend
                ? (smsReason ?? '')
                : (l as any).smsUnreadCount
                  ? `${(l as any).smsUnreadCount} réponse(s) non lue(s)`
                  : (l as any).hasSmsSent ? 'Renvoyer un SMS' : 'Envoyer un SMS'
            }
            onClick={e => { e.stopPropagation(); onSmsRef.current(l); }}
          >
            <LuMessageSquare size={11} />
            {smsCanSend && (l as any).smsUnreadCount > 0 && (
              <span className='absolute -top-0.5 -right-0.5 w-1.5 h-1.5 rounded-full bg-accent-500 pointer-events-none' />
            )}
          </button>
        )}
        <button
          className='w-6 h-6 rounded flex items-center justify-center hover:bg-canvas text-muted hover:text-ink transition-colors relative'
          title={(l as any).noteCount > 0 || l.notes ? 'Voir les notes' : 'Ajouter une note'}
          onClick={e => { e.stopPropagation(); onNoteRef.current(l); }}
        >
          <LuNotebook size={11} />
          {((l as any).noteCount > 0 || l.notes) && (
            <span className='absolute -top-1 -right-1 min-w-[14px] h-3.5 rounded-full bg-accent-500 text-white text-[8px] font-bold flex items-center justify-center px-0.5 pointer-events-none leading-none'>
              {(l as any).noteCount > 0 ? (l as any).noteCount : ''}
            </span>
          )}
        </button>
        {(l as any).status === 'qualifie' && (
          existingClientNamesRef.current.has(l.name.toLowerCase()) ? (
            <span className='w-6 h-6 rounded flex items-center justify-center text-muted' title='Déjà ajouté comme client'>
              <LuUserCheck size={11} />
            </span>
          ) : (
            <button
              className='w-6 h-6 rounded flex items-center justify-center hover:bg-canvas text-emerald-600 hover:text-emerald-700 transition-colors'
              title='Créer un client depuis ce prospect — ajoute ce contact dans la page Clients avec ses informations pré-remplies'
              onClick={e => { e.stopPropagation(); onConvertRef.current(l); }}
            >
              <LuUserPlus size={11} />
            </button>
          )
        )}
      </div>
    );
    // Everything else is read through refs to keep this stable; the SMS and email
    // capabilities must be real deps or the buttons would keep the optimistic
    // "enabled" value they had while the queries were still loading.
  }, [smsCanSend, smsReason, emailCanSend, emailReason]);

  if (statusConfigs.length === 0) {
    return <div className='text-muted text-sm py-8 text-center'>Chargement des statuts…</div>;
  }

  return (
    <>
      <LeadKanbanBoard
        leads={filteredLeads}
        statusConfigs={statusConfigs}
        updateStatus={updateStatus}
        reorder={reorder}
        refetch={refetch}
        cardActions={cardActionsForLead}
        onCardClick={lead => onOpenDetailRef.current(lead)}
        selectedLeadId={selectedLeadId}
        columnExtra={keyField => keyField === 'nouveau' ? (
          <>
            <button
              className='w-5 h-5 rounded flex items-center justify-center text-muted hover:text-ink hover:bg-canvas transition-colors shrink-0'
              title='Ajouter un prospect manuellement'
              onClick={e => { e.stopPropagation(); onAddLead(); }}
            >
              <LuPlus size={12} />
            </button>
            <button
              className='w-5 h-5 rounded flex items-center justify-center text-muted hover:text-ink hover:bg-canvas transition-colors shrink-0'
              title='Chercher plus de prospects sur Google Maps avec les mêmes critères'
              onClick={e => { e.stopPropagation(); onFetchMore(); }}
              disabled={fetchingMore}
            >
              {fetchingMore ? <LuLoader size={12} className='animate-spin' /> : <LuSearch size={12} />}
            </button>
          </>
        ) : undefined}
        mobileColumnExtra={col => col.key === 'nouveau' ? (
          <>
            <button
              className='w-6 h-6 rounded flex items-center justify-center text-muted hover:text-ink hover:bg-canvas'
              title='Ajouter un prospect manuellement'
              onClick={e => { e.stopPropagation(); onAddLead(); }}
            >
              <LuPlus size={12} />
            </button>
            <button
              className='w-6 h-6 rounded flex items-center justify-center text-muted hover:text-ink hover:bg-canvas'
              title='Chercher plus de prospects sur Google Maps'
              onClick={e => { e.stopPropagation(); onFetchMore(); }}
              disabled={fetchingMore}
            >
              {fetchingMore ? <LuLoader size={12} className='animate-spin' /> : <LuSearch size={12} />}
            </button>
          </>
        ) : undefined}
        searchBarSlot={(() => {
          const chips: { key: string; label: string; title: string }[] = [
            { key: 'has_email', label: '✉ Avec courriel', title: 'Afficher uniquement les prospects avec un courriel' },
            { key: 'no_email', label: '✉ Sans courriel', title: 'Afficher uniquement les prospects sans courriel' },
            { key: 'no_website', label: '🌐 Sans site web', title: 'Afficher uniquement les prospects sans site web' },
            { key: 'email_mismatch', label: '⚠ Courriel hors domaine', title: 'Courriel dont le domaine ne correspond pas au site web (opportunité de vente)' },
          ];
          const isFiltered = activeFilters.size > 0 || searchQuery.trim() !== '';
          return (
            <>
            {selectedVisible.length > 0 && (
              <div className='mb-3 flex items-center gap-3 flex-wrap rounded-xl border border-accent-100 bg-accent-50 px-3 py-2'>
                <span className='text-sm font-medium'>{selectedVisible.length} sélectionné(s)</span>
                <button
                  className='text-xs text-muted hover:text-ink underline'
                  onClick={() => setSelectedIds(new Set())}
                >
                  Tout désélectionner
                </button>
                <button
                  className='btn-danger gap-1.5 text-sm ml-auto'
                  onClick={() => onBulkDelete(selectedVisible)}
                >
                  <LuTrash2 size={14} />
                  Supprimer
                </button>
              </div>
            )}
            <div className='flex items-center gap-2 flex-wrap pb-3'>
              <div className='relative'>
                <LuSearch size={13} className='absolute left-2.5 top-1/2 -translate-y-1/2 text-muted pointer-events-none' />
                <input
                  type='text'
                  value={searchQuery}
                  onChange={e => setSearchQuery(e.target.value)}
                  placeholder='Rechercher…'
                  className='text-xs pl-7 pr-2.5 py-1 rounded-full border border-line bg-canvas text-ink placeholder-muted focus:outline-none focus:border-accent-400 w-40'
                />
              </div>
              {chips.map(c => (
                <button
                  key={c.key}
                  title={c.title}
                  onClick={() => toggleFilter(c.key)}
                  className={`text-xs px-2.5 py-1 rounded-full border transition-colors ${
                    activeFilters.has(c.key)
                      ? 'bg-accent-600 border-accent-600 text-white'
                      : 'bg-canvas border-line text-muted hover:border-accent-400 hover:text-ink'
                  }`}
                >
                  {c.label}
                </button>
              ))}
              {isFiltered && (
                <button
                  onClick={() => onResetFilters()}
                  className='text-xs px-2 py-1 text-muted hover:text-ink transition-colors'
                  title='Réinitialiser les filtres'
                >
                  Réinitialiser
                </button>
              )}
              {isFiltered && (
                <span className='text-xs text-muted ml-auto'>
                  {filteredLeads.length} / {leads.length} prospect{leads.length !== 1 ? 's' : ''}
                </span>
              )}
            </div>
            </>
          );
        })()}
        selectedIds={selectedIds}
        onToggleSelect={onToggleSelect}
        onSelectMany={selectMany}
      />
    </>
  );
}

// ─── Leads table ─────────────────────────────────────────────────────────────

function LeadsBoard({ searchId, onBack }: { searchId: string; onBack: () => void }) {
  const [searchParams, setSearchParams] = useSearchParams();

  const { data: search, isLoading, refetch } = useQuery(getLeadSearchDetail, { searchId });
  const { data: statusConfigs = [], refetch: refetchStatuses } = useQuery(getLeadStatusConfigs);
  const { data: existingClients = [] } = useQuery(getClients);
  const existingClientNames = useMemo(
    () => new Set((existingClients as any[]).map((c: any) => c.name.toLowerCase())),
    [existingClients],
  );
  const { ask, Dialog: ConfirmDialog } = useConfirm();
  const navigate = useNavigate();
  const kanbanQuery = searchParams.get('kq') ?? '';
  function setKanbanQuery(val: string) {
    setSearchParams(prev => { const next = new URLSearchParams(prev); if (val) next.set('kq', val); else next.delete('kq'); return next; });
  }
  const kanbanFiltersRaw = searchParams.get('kf') ?? '';
  const kanbanActiveFilters = useMemo(() => new Set(kanbanFiltersRaw ? kanbanFiltersRaw.split(',') : []), [kanbanFiltersRaw]);
  function setKanbanActiveFilters(fn: (prev: Set<string>) => Set<string>) {
    const next = fn(kanbanActiveFilters);
    setSearchParams(prev => { const p = new URLSearchParams(prev); const arr = [...next]; if (arr.length) p.set('kf', arr.join(',')); else p.delete('kf'); return p; });
  }
  function resetKanbanFilters() {
    setSearchParams(prev => { const p = new URLSearchParams(prev); p.delete('kf'); p.delete('kq'); return p; });
  }
  // Lead shown in the right-side detail panel (kept in the URL so it survives
  // a reload and can be shared).
  const detailLeadId = searchParams.get('lead');
  function setDetailLeadId(id: string | null) {
    setSearchParams(prev => {
      const next = new URLSearchParams(prev);
      if (id) next.set('lead', id); else next.delete('lead');
      return next;
    }, { replace: true });
  }
  // The content is inset just enough to clear the panel. `main` is centred with
  // its own padding, so the free space on the right is measured rather than
  // assumed — otherwise the board would stop far short of the panel.
  const contentRef = useRef<HTMLDivElement>(null);
  const [panelInset, setPanelInset] = useState(0);
  useEffect(() => {
    function measure() {
      const el = contentRef.current;
      if (!el) return;
      const panelWidth = window.innerWidth >= 1024 ? 420 : window.innerWidth >= 640 ? 380 : 0;
      if (!detailLeadId || !panelWidth) {
        setPanelInset(0);
        return;
      }
      const free = window.innerWidth - el.getBoundingClientRect().right;
      // +12 gap to the panel, +16 for the board's own `-mx-4` bleed.
      setPanelInset(Math.max(0, panelWidth + 28 - free));
    }
    measure();
    window.addEventListener('resize', measure);
    return () => window.removeEventListener('resize', measure);
  }, [detailLeadId]);

  const [noteTarget, setNoteTarget] = useState<Lead | null>(null);
  const [emailTarget, setEmailTarget] = useState<Lead | null>(null);
  const [convertTarget, setConvertTarget] = useState<Lead | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<Lead | null>(null);
  const [deleting, setDeleting] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  // Leads awaiting bulk-delete confirmation. The board passes the cards it has
  // on screen, so a card hidden by a filter can never be deleted by accident.
  const [bulkTarget, setBulkTarget] = useState<Lead[] | null>(null);
  const [bulkDeleting, setBulkDeleting] = useState(false);

  function toggleLeadSelection(id: string) {
    setSelectedIds(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  }
  const [converting, setConverting] = useState(false);
  const [exporting, setExporting] = useState(false);
  const [smsTarget, setSmsTarget] = useState<Lead | null>(null);
  const [showTemplates, setShowTemplates] = useState(false);
  const [showAddLead, setShowAddLead] = useState(false);
  const [showDetails, setShowDetails] = useState(false);
  const [showFetchMore, setShowFetchMore] = useState(false);
  const [fetchingMore, setFetchingMore] = useState(false);
  const [showShareModal, setShowShareModal] = useState(false);

  async function handleDeleteLead(lead: Lead) {
    setDeleting(true);
    try {
      await (deleteLead as any)({ leadId: lead.id });
      setDeleteTarget(null);
      if (detailLeadId === lead.id) setDetailLeadId(null);
      refetch();
    } catch (e: any) {
      toast.error(e?.message ?? 'Erreur lors de la suppression');
    } finally {
      setDeleting(false);
    }
  }

  async function handleConvertToClient(lead: Lead) {
    setConverting(true);
    try {
      await createClient({
        name: lead.name,
        email: (lead as any).email ?? undefined,
        phone: (lead as any).phone ?? undefined,
        address: (lead as any).address ?? undefined,
        status: 'prospect',
      });
      toast.success(`${lead.name} ajouté comme client`);
      setConvertTarget(null);
      navigate(`/clients?q=${encodeURIComponent(lead.name)}&status=prospect`);
    } catch (e: any) {
      toast.error(e?.message ?? 'Erreur lors de la création du client');
    } finally {
      setConverting(false);
    }
  }

  if (isLoading) {
    return <div className='text-muted'>Chargement…</div>;
  }
  if (!search) return null;

  const leads: Lead[] = (search as any).leads ?? [];
  const filters: any = (search as any).filters ?? {};
  const detailLead: Lead | null = detailLeadId
    ? leads.find(l => l.id === detailLeadId) ?? null
    : null;

  // Criteria of this search, shown read-only in the details modal.
  const detailsValues = {
    ...defaultForm(),
    title: search.title,
    description: (search as any).description ?? '',
    purpose: (search as any).purpose ?? '',
    businessType: filters.businessType ?? '',
    city: filters.city ?? '',
    province: filters.province ?? 'QC',
    radius: filters.radius ?? 10000,
    minRating: filters.minRating ?? 0,
    requireWebsite: filters.requireWebsite ?? false,
    maxResults: filters.maxResults ?? 20,
    language: filters.language ?? 'fr',
  };

  async function handleBulkDelete() {
    const ids = (bulkTarget ?? []).map(l => l.id);
    if (ids.length === 0) return;
    setBulkDeleting(true);
    try {
      await (deleteLeads as any)({ leadIds: ids });
      if (detailLeadId && ids.includes(detailLeadId)) setDetailLeadId(null);
      setSelectedIds(new Set());
      setBulkTarget(null);
      toast.success(`${ids.length} prospect(s) supprimé(s)`);
      refetch();
    } catch (e: any) {
      toast.error(e?.message ?? 'Erreur lors de la suppression');
    } finally {
      setBulkDeleting(false);
    }
  }

  async function handleExport() {
    setExporting(true);
    try {
      const { csv } = await exportLeads({ searchId });
      const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${(search?.title ?? 'export').replace(/[^a-z0-9]/gi, '_')}.csv`;
      a.click();
      URL.revokeObjectURL(url);
    } catch {
      toast.error('Erreur lors de l\'export');
    } finally {
      setExporting(false);
    }
  }

  return (
    <>
      {ConfirmDialog}

      {/* Right-side detail panel */}
      <LeadDetailPanel
        lead={detailLead}
        statusConfigs={statusConfigs as LeadStatusConfig[]}
        existingClientNames={existingClientNames}
        onClose={() => setDetailLeadId(null)}
        onRefetch={refetch}
        onEmail={setEmailTarget}
        onSms={setSmsTarget}
        onConvert={setConvertTarget}
        onDelete={setDeleteTarget}
      />

      {/* Delete confirmation */}
      <Modal
        open={deleteTarget !== null}
        title={deleteTarget ? `Supprimer — ${deleteTarget.name}` : 'Supprimer'}
        onClose={() => setDeleteTarget(null)}
      >
        <LeadDeleteConfirmModal
          lead={deleteTarget}
          onClose={() => setDeleteTarget(null)}
          onConfirm={() => handleDeleteLead(deleteTarget!)}
          deleting={deleting}
        />
      </Modal>

      {/* Bulk delete confirmation */}
      <Modal
        open={bulkTarget !== null}
        title={`Supprimer ${bulkTarget?.length ?? 0} prospect(s)`}
        onClose={() => setBulkTarget(null)}
      >
        <div className='space-y-4'>
          <p className='text-sm text-muted'>
            Êtes-vous sûr de vouloir supprimer {bulkTarget?.length ?? 0} prospect(s) ? Cette action est irréversible.
          </p>
          <div className='rounded-xl border border-line bg-canvas p-3.5 text-sm max-h-48 overflow-y-auto space-y-1'>
            {(bulkTarget ?? []).slice(0, 20).map(l => (
              <div key={l.id} className='font-medium'>{l.name}</div>
            ))}
            {(bulkTarget?.length ?? 0) > 20 && (
              <div className='text-muted'>et {(bulkTarget?.length ?? 0) - 20} autre(s)…</div>
            )}
          </div>
          <div className='flex justify-end gap-2'>
            <button className='btn-secondary' onClick={() => setBulkTarget(null)} disabled={bulkDeleting}>
              Annuler
            </button>
            <button className='btn-danger gap-1.5' onClick={handleBulkDelete} disabled={bulkDeleting}>
              {bulkDeleting ? <LuLoader size={14} className='animate-spin' /> : <LuTrash2 size={14} />}
              {bulkDeleting ? 'Suppression…' : 'Supprimer'}
            </button>
          </div>
        </div>
      </Modal>

      <Modal
        open={emailTarget !== null}
        title={emailTarget ? `${(emailTarget as any).hasEmailSent ? 'Réenvoyer' : 'Envoyer'} un courriel — ${emailTarget.name}` : 'Envoyer un courriel'}
        onClose={() => setEmailTarget(null)}
      >
        {emailTarget && (
          <ProspectEmailModal lead={emailTarget} searchTitle={search.title} onClose={() => setEmailTarget(null)} onSent={refetch} />
        )}
      </Modal>
      <Modal
        open={noteTarget !== null}
        title={noteTarget ? `Note — ${noteTarget.name}` : 'Note'}
        onClose={() => setNoteTarget(null)}
      >
        {noteTarget && (
          <NoteModal lead={noteTarget} onClose={() => { setNoteTarget(null); refetch(); }} />
        )}
      </Modal>
      {/* Search criteria, with the "find more prospects" action attached to them */}
      <Modal
        open={showDetails}
        title='Détails de la recherche'
        onClose={() => setShowDetails(false)}
      >
        {showDetails && (
          <SearchForm
            readOnly
            onClose={() => setShowDetails(false)}
            onDone={() => setShowDetails(false)}
            initialValues={detailsValues}
            footerExtra={
              <button
                className='btn-primary gap-1.5 mr-auto'
                onClick={() => { setShowDetails(false); setShowFetchMore(true); }}
              >
                <LuSearch size={14} />
                Chercher plus de prospects
              </button>
            }
          />
        )}
      </Modal>

      <FetchMoreLeadsModal
        open={showFetchMore}
        searchId={searchId}
        searchFilters={filters}
        searchTitle={search.title}
        searchPurpose={(search as any).purpose ?? undefined}
        onClose={() => setShowFetchMore(false)}
        onAdded={refetch}
        onBusyChange={setFetchingMore}
      />

      <Modal
        open={showAddLead}
        title='Ajouter un prospect'
        onClose={() => setShowAddLead(false)}
      >
        {showAddLead && (
          <AddLeadModal
            searchId={searchId}
            statusConfigs={statusConfigs as LeadStatusConfig[]}
            onClose={() => setShowAddLead(false)}
            onCreated={lead => { refetch(); setDetailLeadId(lead.id); }}
          />
        )}
      </Modal>
      <Modal
        open={showTemplates}
        title='Modèles de messages'
        onClose={() => setShowTemplates(false)}
      >
        {showTemplates && (
          <TemplatesModal
            searchId={searchId}
            searchTitle={search.title}
            statusConfigs={statusConfigs as LeadStatusConfig[]}
            onClose={() => setShowTemplates(false)}
          />
        )}
      </Modal>
      <Modal
        open={smsTarget !== null}
        title={smsTarget ? `${(smsTarget as any).hasSmsSent ? 'Renvoyer' : 'Envoyer'} un SMS — ${smsTarget.name}` : 'Envoyer un SMS'}
        onClose={() => setSmsTarget(null)}
      >
        {smsTarget && (
          <ProspectSmsModal
            lead={smsTarget}
            searchTitle={search.title}
            onClose={() => setSmsTarget(null)}
            onSent={refetch}
          />
        )}
      </Modal>
      <Modal
        open={showShareModal}
        title='Partager avec un employé'
        onClose={() => setShowShareModal(false)}
      >
        {showShareModal && (
          <ShareProspectModal
            searchId={searchId}
            onClose={() => setShowShareModal(false)}
          />
        )}
      </Modal>
      <Modal
        open={convertTarget !== null}
        title={convertTarget ? `Créer un client — ${convertTarget.name}` : 'Créer un client'}
        onClose={() => setConvertTarget(null)}
      >
        {convertTarget && (
          <div className='space-y-4'>
            <p className='text-sm text-muted'>
              Ce prospect qualifié sera ajouté à votre page Clients avec les informations suivantes. Vous pourrez compléter son profil par la suite.
            </p>
            <div className='rounded-xl border border-line bg-canvas p-3.5 space-y-1.5 text-sm'>
              <div><span className='text-muted'>Nom :</span> <span className='font-medium'>{convertTarget.name}</span></div>
              {(convertTarget as any).email && <div><span className='text-muted'>Courriel :</span> {(convertTarget as any).email}</div>}
              {(convertTarget as any).phone && <div><span className='text-muted'>Téléphone :</span> {(convertTarget as any).phone}</div>}
              {(convertTarget as any).address && <div><span className='text-muted'>Adresse :</span> {(convertTarget as any).address}</div>}
            </div>
            <div className='flex justify-end gap-2'>
              <button className='btn-secondary' onClick={() => setConvertTarget(null)} disabled={converting}>
                Annuler
              </button>
              <button
                className='btn-primary gap-1.5'
                onClick={() => handleConvertToClient(convertTarget)}
                disabled={converting}
              >
                {converting ? <LuLoader size={14} className='animate-spin' /> : <LuUserPlus size={14} />}
                {converting ? 'Création…' : 'Créer le client'}
              </button>
            </div>
          </div>
        )}
      </Modal>

      {/*
        While the panel is open the content is inset so the board keeps its own
        horizontal scroll and every column stays reachable instead of hiding
        underneath the panel. The outer div is never inset — it's the reference
        used to measure the free space on the right.
      */}
      <div ref={contentRef}>
      <div
        className='transition-[margin] duration-200'
        style={panelInset ? { marginRight: panelInset } : undefined}
      >
      {/* Header */}
      <div className='flex flex-col gap-3 mb-5'>
        {/* Top row: title + actions */}
        <div className='flex items-start gap-2 sm:gap-4'>
          {/* Title block */}
          <div className='flex-1 min-w-0'>
            <div className='flex items-center gap-1.5'>
              <h2 className='text-base sm:text-lg font-semibold truncate'>{search.title}</h2>
              <button
                className='w-6 h-6 rounded flex items-center justify-center hover:bg-canvas text-muted hover:text-ink transition-colors shrink-0'
                title='Détails de la recherche'
                onClick={() => setShowDetails(true)}
              >
                <LuEye size={14} />
              </button>
            </div>
            {search.description && (
              <p className='text-sm text-muted italic'>{search.description}</p>
            )}
            {(search as any).purpose && (
              <p className='text-xs text-muted'>Objectif : {(search as any).purpose}</p>
            )}
            <div className='flex flex-wrap gap-1.5 mt-1'>
              {filters.businessType && (
                <span className='badge-info'>{filters.businessType}</span>
              )}
              {filters.city && (
                <span className='badge-neutral flex items-center gap-1'>
                  <LuMapPin size={11} />{filters.city}{filters.province ? `, ${filters.province}` : ''}
                </span>
              )}
              {filters.radius && (
                <span className='badge-neutral'>
                  {RADIUS_OPTIONS.find(r => r.value === filters.radius)?.label ?? `${filters.radius / 1000} km`}
                </span>
              )}
              {filters.minRating > 0 && (
                <span className='badge-neutral flex items-center gap-1'>
                  <LuStar size={11} />{filters.minRating}+
                </span>
              )}
              {filters.requireWebsite && (
                <span className='badge-neutral flex items-center gap-1'>
                  <LuGlobe size={11} />Site web requis
                </span>
              )}
              {filters.language && (
                <span className='badge-neutral'>{filters.language === 'fr' ? 'Français' : 'English'}</span>
              )}
              <span className='text-xs text-muted self-center'>{leads.length} prospect(s)</span>
            </div>
          </div>
        </div>

        {/* Action bar (wraps on mobile) */}
        <div className='flex items-center gap-2 flex-wrap'>
          <button className='btn-ghost gap-1.5 text-sm' onClick={() => setShowTemplates(true)}>
            <LuFilePen size={14} />
            <span className='hidden xs:inline'>Modèles courriel / SMS</span>
            <span className='xs:hidden'>Modèles</span>
          </button>
          <button className='btn-secondary gap-1.5 text-sm' onClick={handleExport} disabled={exporting}>
            {exporting ? <LuLoader size={14} className='animate-spin' /> : <LuDownload size={14} />}
            <span className='hidden xs:inline'>Exporter CSV</span>
            <span className='xs:hidden'>CSV</span>
          </button>

        </div>
      </div>

      <LeadsKanban
          leads={leads}
          statusConfigs={statusConfigs as LeadStatusConfig[]}
          searchId={searchId}
          searchFilters={filters}
          searchTitle={search.title}
          searchPurpose={(search as any).purpose ?? undefined}
          refetch={refetch}
          onNote={setNoteTarget}
          onEmail={setEmailTarget}
          onSms={setSmsTarget}
          onConvert={setConvertTarget}
          onOpenDetail={lead => setDetailLeadId(lead.id)}
          selectedLeadId={detailLeadId}
          existingClientNames={existingClientNames}
          searchQuery={kanbanQuery}
          setSearchQuery={setKanbanQuery}
          activeFilters={kanbanActiveFilters}
          setActiveFilters={setKanbanActiveFilters}
          onResetFilters={resetKanbanFilters}
          selectedIds={selectedIds}
          setSelectedIds={setSelectedIds}
          onToggleSelect={toggleLeadSelection}
          onBulkDelete={setBulkTarget}
          onAddLead={() => setShowAddLead(true)}
          onFetchMore={() => setShowFetchMore(true)}
          fetchingMore={fetchingMore}
        />
      </div>
      </div>
    </>
  );
}

// ─── Search list ──────────────────────────────────────────────────────────────

function EditSearchModal({ search, onClose }: { search: { id: string; title: string; purpose?: string | null }; onClose: () => void }) {
  const [form, setForm] = useState({ title: search.title, purpose: search.purpose ?? '' });
  const [saving, setSaving] = useState(false);
  const { data: searches, refetch } = useQuery(getLeadSearches);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!form.title.trim()) return;
    setSaving(true);
    try {
      // @ts-ignore
      await updateLeadSearch({ id: search.id, title: form.title, purpose: form.purpose || null });
      await refetch();
      toast.success('Prospection mise à jour');
      onClose();
    } catch {
      toast.error('Erreur lors de la mise à jour');
    } finally {
      setSaving(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} className='flex flex-col gap-4'>
      <div>
        <label className='label'>Titre</label>
        <MagicInput
          className='input'
          value={form.title}
          onChange={e => setForm(f => ({ ...f, title: e.target.value }))}
          placeholder='Titre de la recherche'
          autoFocus
          required
        />
      </div>
      <div>
        <label className='label'>
          Objectif <span className='text-muted font-normal'>(optionnel)</span>
        </label>
        <MagicInput
          className='input'
          value={form.purpose}
          onChange={e => setForm(f => ({ ...f, purpose: e.target.value }))}
          placeholder='Ex : proposer une refonte de site web, offrir un audit SEO gratuit…'
        />
        <p className='text-xs text-muted mt-1'>
          L'IA utilise cet objectif pour rédiger les courriels de tous les prospects de cette prospection.
          Si vide, elle adapte le message selon le contexte du prospect.
        </p>
      </div>
      <div className='flex justify-end gap-2 pt-1'>
        <button type='button' className='btn-ghost' onClick={onClose}>Annuler</button>
        <button type='submit' className='btn-primary' disabled={saving}>
          {saving ? 'Enregistrement…' : 'Enregistrer'}
        </button>
      </div>
    </form>
  );
}

function SearchList({
  onSelect,
  onNew,
  onDuplicate,
}: {
  onSelect: (id: string) => void;
  onNew: () => void;
  onDuplicate: (values: Partial<ReturnType<typeof defaultForm>>) => void;
}) {
  const { data: searches, isLoading } = useQuery(getLeadSearches);
  // @ts-ignore -- generated by Wasp on next restart
  const { data: smsAlerts } = useQuery(getSmsReplyAlerts, undefined, { refetchInterval: 60_000 });
  const unreadBySearch: Record<string, number> = (smsAlerts as any)?.bySearch ?? {};
  const { ask, Dialog: ConfirmDialog } = useConfirm();
  const [editTarget, setEditTarget] = useState<{ id: string; title: string; purpose?: string | null } | null>(null);
  const [shareTargetId, setShareTargetId] = useState<string | null>(null);

  async function handleDelete(id: string, title: string) {
    if (await ask(`Supprimer la recherche « ${title} » ?`, { description: 'Tous les prospects associés seront supprimés.' })) {
      try {
        await deleteLeadSearch({ id });
        toast.success('Recherche supprimée');
      } catch {
        toast.error('Erreur lors de la suppression');
      }
    }
  }

  if (isLoading) return <div className='text-muted text-sm'>Chargement…</div>;

  const list = searches ?? [];

  if (list.length === 0) {
    return (
      <EmptyState
        title='Aucune recherche'
        description='Lancez votre première prospection pour trouver des clients potentiels.'
        action={<button className='btn-primary' onClick={onNew}>Nouvelle recherche</button>}
      />
    );
  }

  return (
    <>
      {ConfirmDialog}
      <Modal
        open={editTarget !== null}
        title='Modifier la prospection'
        onClose={() => setEditTarget(null)}
      >
        {editTarget && (
          <EditSearchModal search={editTarget} onClose={() => setEditTarget(null)} />
        )}
      </Modal>
      <Modal
        open={shareTargetId !== null}
        title='Partager avec un employé'
        onClose={() => setShareTargetId(null)}
      >
        {shareTargetId && (
          <ShareProspectModal searchId={shareTargetId} onClose={() => setShareTargetId(null)} />
        )}
      </Modal>
      <div className='grid md:grid-cols-2 lg:grid-cols-3 gap-4'>
        {list.map((s: any) => {
          const f: any = s.filters ?? {};
          const leadCount = s.leads?.length ?? s.totalFound ?? 0;
          return (
            <div
              key={s.id}
              role='button'
              tabIndex={0}
              className='card p-5 text-left hover:border-accent-300 transition-colors group cursor-pointer w-full'
              onClick={() => onSelect(s.id)}
              onKeyDown={e => e.key === 'Enter' && onSelect(s.id)}
            >
              <div className='flex items-start justify-between gap-2'>
                <h3 className='font-semibold text-sm leading-tight group-hover:text-accent-700 transition-colors'>
                  {s.title}
                  {unreadBySearch[s.id] > 0 && (
                    <span
                      className='ml-1.5 align-middle inline-flex items-center gap-1 rounded-full bg-accent-500 text-white text-[10px] font-bold px-1.5 h-[16px]'
                      title={`${unreadBySearch[s.id]} réponse(s) SMS non lue(s)`}
                    >
                      <LuMessageSquare size={9} />
                      {unreadBySearch[s.id]}
                    </span>
                  )}
                </h3>
                <div onClick={e => e.stopPropagation()} className='flex items-center gap-1'>
                  <IconBtn
                    title='Partager avec un employé'
                    onClick={() => setShareTargetId(s.id)}
                  >
                    <LuShare2 size={14} />
                  </IconBtn>
                  <IconBtn
                    title='Modifier'
                    onClick={() => setEditTarget({ id: s.id, title: s.title, purpose: s.purpose ?? null })}
                  >
                    <LuPencil size={14} />
                  </IconBtn>
                  <IconBtn
                    title='Dupliquer les filtres'
                    onClick={() => onDuplicate({
                      title: `${s.title} (copie)`,
                      purpose: s.purpose ?? '',
                      businessType: f.businessType ?? '',
                      city: f.city ?? '',
                      province: f.province ?? 'QC',
                      radius: f.radius ?? 10000,
                      minRating: f.minRating ?? 0,
                      requireWebsite: f.requireWebsite ?? false,
                      maxResults: f.maxResults ?? 20,
                      language: f.language ?? 'fr',
                    })}
                  >
                    <LuCopyPlus size={14} />
                  </IconBtn>
                  <IconBtn
                    variant='danger'
                    title='Supprimer'
                    onClick={() => handleDelete(s.id, s.title)}
                  >
                    <TrashIcon />
                  </IconBtn>
                </div>
              </div>

              {s.description && (
                <p className='text-xs text-muted mt-1 line-clamp-2'>{s.description}</p>
              )}

              <div className='mt-3 flex items-center gap-2 text-xs text-muted'>
                {f.businessType && (
                  <span className='badge-neutral'>{f.businessType}</span>
                )}
                {f.city && (
                  <span className='flex items-center gap-1'>
                    <LuMapPin size={10} /> {f.city}
                  </span>
                )}
              </div>

              <div className='mt-3 flex items-center gap-1.5 text-xs'>
                <LuUsers size={12} className='text-accent-600' />
                <span className='font-semibold text-accent-700'>{leadCount}</span>
                <span className='text-muted'>prospect(s)</span>
              </div>
            </div>
          );
        })}
      </div>
    </>
  );
}

// ─── Page ─────────────────────────────────────────────────────────────────────

export default function LeadSearchPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const selectedId = searchParams.get('id');
  const [showForm, setShowForm] = useState(false);
  const [formPrefill, setFormPrefill] = useState<Partial<ReturnType<typeof defaultForm>> | undefined>(undefined);
  const [showManageStatuses, setShowManageStatuses] = useState(false);
  const { data: statusConfigs = [], refetch: refetchStatuses } = useQuery(getLeadStatusConfigs);

  function handleDone(id: string) {
    setShowForm(false);
    setFormPrefill(undefined);
    setSearchParams({ id });
  }

  function handleSelect(id: string) {
    setSearchParams({ id });
  }

  function handleBack() {
    setSearchParams({});
  }

  function handleDuplicate(values: Partial<ReturnType<typeof defaultForm>>) {
    setFormPrefill({ ...defaultForm(), ...values });
    setShowForm(true);
  }

  return (
    <>
      <Modal
        open={showManageStatuses}
        title='Gérer les statuts'
        onClose={() => setShowManageStatuses(false)}
      >
        <ManageStatusesModal
          configs={statusConfigs as LeadStatusConfig[]}
          onRefresh={refetchStatuses}
          onClose={() => setShowManageStatuses(false)}
        />
      </Modal>
      <Modal
        open={showForm}
        title={formPrefill ? 'Dupliquer la recherche' : 'Nouvelle prospection'}
        onClose={() => { setShowForm(false); setFormPrefill(undefined); }}
      >
        <SearchForm
          onClose={() => { setShowForm(false); setFormPrefill(undefined); }}
          onDone={handleDone}
          initialValues={formPrefill}
        />
      </Modal>

      <PageHeader
        title='Prospection'
        subtitle={selectedId ? undefined : 'Trouvez des entreprises à démarcher à partir de Google Maps.'}
        onBack={selectedId ? handleBack : undefined}
        actions={
          <div className='flex items-center gap-2'>
            {!selectedId && (
              <>
                <button className='btn-secondary gap-1.5' onClick={() => setShowManageStatuses(true)}>
                  <LuSlidersHorizontal size={14} />
                  Statuts
                </button>
                <button className='btn-primary gap-2' onClick={() => setShowForm(true)}>
                  <LuSearch size={16} />
                  Nouvelle recherche
                </button>
              </>
            )}
          </div>
        }
      />

      {selectedId ? (
        <LeadsBoard searchId={selectedId} onBack={handleBack} />
      ) : (
        <SearchList onSelect={handleSelect} onNew={() => setShowForm(true)} onDuplicate={handleDuplicate} />
      )}
    </>
  );
}
